 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v text;
BEGIN
  v := NULLIF(current_setting('app.estoque_mov_ctx', true), '');
  IF v IS NULL THEN RETURN NULL; END IF;
