$function$

CREATE OR REPLACE FUNCTION public.fn_financial_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old jsonb; v_new jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN v_new := to_jsonb(NEW);
  ELSIF TG_OP = 'UPDATE' THEN v_old := to_jsonb(OLD); v_new := to_jsonb(NEW);
  ELSIF TG_OP = 'DELETE' THEN v_old := to_jsonb(OLD);
  END IF;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, old_data, new_data, performed_by)
  VALUES (TG_TABLE_NAME, COALESCE((NEW).id, (OLD).id), TG_OP, v_old, v_new, auth.uid());

  RETURN COALESCE(NEW, OLD);
END $function$

CREATE OR REPLACE FUNCTION public.fn_generate_receivable_installments()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  i int;
  v_context platform_private.financial_initial_installments;
  v_inst jsonb;
  v_qtd int := NEW.installment_count;
  v_base numeric(14,2) := ROUND(NEW.total_amount / v_qtd, 2);
  v_acc numeric(14,2) := 0;
  v_amt numeric(14,2);
BEGIN
  IF NEW.organization_id IS NULL THEN
    RAISE EXCEPTION 'FINANCIAL_TENANT_REQUIRED' USING ERRCODE = '23514';
  END IF;
  DELETE FROM platform_private.financial_initial_installments
    WHERE transaction_id=txid_current() AND title_id=NEW.id AND kind='receivable'
    RETURNING * INTO v_context;
  IF FOUND THEN
    IF v_context.actor_id IS DISTINCT FROM auth.uid() OR v_context.organization_id IS DISTINCT FROM NEW.organization_id
       OR NEW.created_by IS DISTINCT FROM v_context.actor_id OR NEW.origin_type <> 'MANUAL'
       OR platform_private.h15_actor_organization() IS DISTINCT FROM NEW.organization_id
       OR NOT public.is_financial_staff(auth.uid()) THEN
      RAISE EXCEPTION 'FIN_INITIAL_CONTEXT_DENIED' USING ERRCODE='42501';
    END IF;
    IF jsonb_array_length(v_context.installments) <> NEW.installment_count
       OR (SELECT sum((x->>'amount')::numeric) FROM jsonb_array_elements(v_context.installments) x) IS DISTINCT FROM NEW.total_amount THEN
      RAISE EXCEPTION 'FIN_TITLE_INVALID_SUM' USING ERRCODE='23514';
    END IF;
    FOR v_inst IN SELECT * FROM jsonb_array_elements(v_context.installments) LOOP
      INSERT INTO public.accounts_receivable_installments(organization_id,receivable_id,installment_number,due_date,original_amount,net_amount,status)
        VALUES(NEW.organization_id,NEW.id,(v_inst->>'installment_number')::int,(v_inst->>'due_date')::date,
          (v_inst->>'amount')::numeric,(v_inst->>'amount')::numeric,'OPEN');
    END LOOP;
    RETURN NEW;
  END IF;
  IF NEW.origin_type='B2B_ORDER' AND EXISTS(SELECT 1 FROM public.partner_orders o WHERE o.id=NEW.origin_id AND o.c2_external_origin_snapshot IS NOT NULL) THEN
    INSERT INTO public.accounts_receivable_installments(receivable_id,installment_number,due_date,original_amount,net_amount,status,organization_id,interest_amount)
    SELECT NEW.id,s.installment_number,s.due_date,s.amount,s.amount,'OPEN',NEW.organization_id,s.interest_amount
    FROM public.partner_order_payment_schedule s JOIN public.partner_orders o ON o.id=s.partner_order_id AND o.payment_terms_id=s.payment_terms_id
    WHERE o.id=NEW.origin_id ORDER BY s.installment_number;
    IF (SELECT count(*) FROM public.accounts_receivable_installments WHERE receivable_id=NEW.id)<>v_qtd THEN RAISE EXCEPTION 'B2B_INSTALLMENT_CARDINALITY_INVALID' USING ERRCODE='23514'; END IF;
    RETURN NEW;
  END IF;
  FOR i IN 1..v_qtd LOOP
    IF i < v_qtd THEN
      v_amt := v_base;
      v_acc := v_acc + v_amt;
    ELSE
      v_amt := NEW.total_amount - v_acc;
    END IF;
    INSERT INTO public.accounts_receivable_installments
      (receivable_id, installment_number, due_date, original_amount, net_amount, status, organization_id)
    VALUES
      (NEW.id, i, (NEW.first_due_date + ((i-1) || ' months')::interval)::date, v_amt, v_amt, 'OPEN', NEW.organization_id);
  END LOOP;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.fn_sync_entrega_financial_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- bloqueia troca de receivable_id já vinculado
  IF TG_OP = 'UPDATE'
     AND OLD.receivable_id IS NOT NULL
     AND NEW.receivable_id IS DISTINCT FROM OLD.receivable_id THEN
    RAISE EXCEPTION 'Esta entrega já possui faturamento gerado e não pode ser alterada.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- vinculou receivable agora => BILLED
  IF (TG_OP = 'INSERT' AND NEW.receivable_id IS NOT NULL)
     OR (TG_OP = 'UPDATE' AND OLD.receivable_id IS NULL AND NEW.receivable_id IS NOT NULL) THEN
    NEW.financial_status := 'BILLED';
    NEW.billing_generated_at := COALESCE(NEW.billing_generated_at, now());
    NEW.billing_generated_by := COALESCE(NEW.billing_generated_by, auth.uid());
  END IF;

  -- entrega cancelada
  IF NEW.status::text = 'cancelada' THEN
    NEW.financial_status := 'CANCELED';
  END IF;

  -- valida NOT_BILLABLE
  IF NEW.financial_status = 'NOT_BILLABLE'
     AND (NEW.not_billable_reason IS NULL OR length(trim(NEW.not_billable_reason)) = 0) THEN
    RAISE EXCEPTION 'Informe o motivo para marcar a entrega como sem cobrança.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- default quando não definido
  IF NEW.financial_status IS NULL THEN
    NEW.financial_status := 'PENDING_BILLING';
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_validate_entrega_confirmacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_anexos int;
BEGIN
  IF NEW.status::text = 'entregue'
     AND (TG_OP = 'INSERT' OR OLD.status::text IS DISTINCT FROM 'entregue') THEN

    IF TG_OP = 'UPDATE' AND OLD.status::text = 'cancelada' THEN
      RAISE EXCEPTION 'Não é possível confirmar uma entrega cancelada.'
        USING ERRCODE = 'check_violation';
    END IF;

    IF COALESCE(TRIM(NEW.recebido_por_nome), '') = '' THEN
      RAISE EXCEPTION 'Informe o nome de quem recebeu a entrega.'
        USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.confirmado_por IS NULL THEN
      RAISE EXCEPTION 'A entrega precisa ser confirmada por um usuário autenticado.'
        USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.entregue_em IS NULL THEN
      NEW.entregue_em := now();
    END IF;

    IF NEW.comprovante_entrega_obrigatorio THEN
      SELECT count(*) INTO v_anexos
        FROM public.entrega_documentos
        WHERE entrega_id = NEW.id;
      IF v_anexos = 0 THEN
        RAISE EXCEPTION 'É obrigatório anexar pelo menos um comprovante para confirmar esta entrega.'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validate_entrega_estoque()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_estoque_id uuid;
  v_qtd_fisica_disponivel numeric;
  v_qtd_reservada_os numeric;
  v_qtd_ja_entregue_lote_os numeric;
  v_lote_codigo text;
BEGIN
  -- Se a entrega já está sendo criada/atualizada como cancelada, não validar saldo
  IF NEW.status::text = 'cancelada' THEN
    RETURN NEW;
  END IF;

  v_estoque_id := NEW.estoque_produto_id;

  IF v_estoque_id IS NULL THEN
    RAISE EXCEPTION 'ID do estoque não informado na entrega.' USING ERRCODE = 'check_violation';
  END IF;

  SELECT 
    ep.quantidade, 
    ep.quantidade_reservada,
    l.codigo_lote
  INTO 
    v_qtd_fisica_disponivel, 
    v_qtd_reservada_os,
    v_lote_codigo
  FROM public.estoque_produto ep
  JOIN public.lotes l ON l.id = ep.lote_id
  WHERE ep.id = v_estoque_id;

  -- Acumula somente entregas válidas (ignora canceladas)
  SELECT COALESCE(SUM(quantidade_entregue), 0)
  INTO v_qtd_ja_entregue_lote_os
  FROM public.entregas
  WHERE estoque_produto_id = v_estoque_id 
    AND ordem_servico_id = NEW.ordem_servico_id
    AND id <> NEW.id
    AND status::text <> 'cancelada';

  IF NEW.quantidade_entregue > v_qtd_fisica_disponivel THEN
    RAISE EXCEPTION 'Saldo físico insuficiente no lote %. Disponível: %, Solicitado: %.',
      v_lote_codigo, v_qtd_fisica_disponivel, NEW.quantidade_entregue
      USING ERRCODE = 'check_violation';
  END IF;

  IF (v_qtd_ja_entregue_lote_os + NEW.quantidade_entregue) > v_qtd_reservada_os THEN
    RAISE EXCEPTION 'Quantidade excede o saldo reservado para esta Ordem de Serviço no lote %. Reservado total: %, Já entregue: %, Saldo restante: %.',
      v_lote_codigo, v_qtd_reservada_os, v_qtd_ja_entregue_lote_os, (v_qtd_reservada_os - v_qtd_ja_entregue_lote_os)
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_b2b_receivable_secure(p_partner_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;

  IF auth.uid() IS NULL THEN
    IF pg_trigger_depth()=0 THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  ELSIF NOT (public.b2b_phase1_order_visible(p_partner_order_id) OR EXISTS (
    SELECT 1 FROM public.partner_orders po WHERE po.id=p_partner_order_id
      AND platform_private.c2p1_settings_allowed(po.partner_id,true))) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF NOT (pg_trigger_depth() > 0 or public.has_role(auth.uid(), 'administrador'::public.app_role)
      or public.has_role(auth.uid(), 'gestor'::public.app_role)
      or public.has_role(auth.uid(), 'financeiro'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
 IF EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_partner_order_id AND internal_origin_snapshot IS NOT NULL) THEN RAISE EXCEPTION 'B2B_INTERNAL_DOWNSTREAM_UNVERIFIED' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_partner_order_id AND c2_external_origin_snapshot->>'contract'='C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1') THEN RAISE EXCEPTION 'C2_ACCOUNTING_PENDING' USING ERRCODE='42501'; END IF;
  IF p_partner_order_id IS NULL THEN
    RAISE EXCEPTION 'partner_order_id_required' USING ERRCODE='P0001';
  END IF;

  -- Canonical row-before-receipt order, matching approval and its billing trigger.
  PERFORM 1 FROM public.partner_orders WHERE id=p_partner_order_id FOR UPDATE;

  -- Serializa concorrencia real (clique duplo / chamadas simultaneas).
  -- Chave unica bigint: assinatura pg_advisory_xact_lock(bigint).
  PERFORM pg_advisory_xact_lock(
    hashtextextended('b2b_receivable:' || p_partner_order_id::text, 0)
  );

  IF NOT public.fn_b2b_order_priceable(p_partner_order_id) THEN
    RAISE EXCEPTION 'order_not_priceable_quote_required' USING ERRCODE='P0001';
  END IF;

  RETURN public.generate_b2b_receivable_secure_impl(p_partner_order_id);
END $function$

CREATE OR REPLACE FUNCTION public.generate_b2b_receivable_secure_impl(p_partner_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_order record;
  v_partner record;
  v_settings record;
  v_terms record;
  v_receivable_id uuid;
  v_category_id uuid;
  v_payment_method_id uuid;
  v_existing uuid;
  v_sch record;
  v_ari_id uuid;
  v_installments_json jsonb := '[]'::jsonb;
  v_system_call boolean := (v_uid IS NULL);
  v_gate jsonb;
  v_fiscal jsonb;
  v_uf text;
  v_org uuid;
  v_org_count integer; -- b2b_f1_financial_tenant
BEGIN
  IF NOT v_system_call THEN
    IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'financeiro') OR has_role(v_uid,'gestor') OR has_role(v_uid,'gestor_comercial')) THEN
      INSERT INTO public.partner_order_audit_logs(order_id, usuario_id, acao, dados_novos)
        VALUES (p_partner_order_id, v_uid, 'financeiro_permissao_negada', jsonb_build_object('motivo','sem permissão'));
      RAISE EXCEPTION 'Sem permissão para gerar cobrança B2B';
    END IF;
  END IF;

  SELECT * INTO v_order FROM public.partner_orders WHERE id = p_partner_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não encontrado'; END IF;

  -- Deterministic partner ownership, never caller-supplied organization.
  SELECT count(*), min(o.id::text)::uuid INTO v_org_count,v_org
    FROM public.organizations o WHERE o.partner_account_id=v_order.partner_id;
  -- c2_ord_owner_tenant: cliente comercial sem tenant próprio fatura no tenant dono.
  IF v_org_count = 0 THEN
    SELECT count(*), min(o.id::text)::uuid INTO v_org_count, v_org
      FROM public.partner_accounts pa JOIN public.organizations o ON o.id = pa.commercial_owner_organization_id
     WHERE pa.id = v_order.partner_id AND pa.ativo IS TRUE AND pa.deleted_at IS NULL
       AND o.ativo IS TRUE AND o.status = 'ativa';
  END IF;
  IF v_org_count <> 1 OR v_org IS NULL THEN
    RAISE EXCEPTION 'B2B_FINANCIAL_TENANT_AMBIGUOUS' USING ERRCODE='42501';
  END IF;
  IF v_uid IS NOT NULL THEN
    -- c2_ord_internal_scope: emissor interno é limitado por h15 = tenant do título (abaixo);
    -- quem tem papel B2B externo continua passando pelo assert canônico.
    IF public.has_role(v_uid,'parceiro_b2b'::app_role) OR public.has_role(v_uid,'parceiro_b2b_tecnico'::app_role) THEN
      PERFORM platform_private.assert_b2b_partner_scope(v_uid,v_order.partner_id);
    END IF;
    IF NOT public.is_platform_superadmin(v_uid) AND public.h15_actor_organization() IS DISTINCT FROM v_org THEN
      RAISE EXCEPTION 'B2B_FINANCIAL_TENANT_MISMATCH' USING ERRCODE='42501';
    END IF;
  END IF;

  IF v_order.c2_external_origin_snapshot IS NOT NULL THEN
    PERFORM platform_private.c2_external_origin_assert(v_order.c2_external_origin_snapshot,v_order.partner_id,v_order.cliente_id);
    IF v_org::text IS DISTINCT FROM v_order.c2_external_origin_snapshot->>'creditor_organization_id' THEN RAISE EXCEPTION 'C2_EXTERNAL_CREDITOR_DRIFT' USING ERRCODE='42501'; END IF;
  END IF;

  -- GATE Fase C: elegibilidade server-side
  v_gate := public.fn_b2b_order_billing_eligibility(p_partner_order_id);
  IF NOT (v_gate->>'eligible')::boolean THEN
    INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
      VALUES (p_partner_order_id, v_order.partner_id, v_uid, 'financeiro_bloqueado_gate', v_gate);
    RAISE EXCEPTION 'billing_not_eligible:%', v_gate->>'reason_code';
  END IF;

  -- H6C-001: condicao canonica vinculada ao pedido (nunca a mais recente).
  SELECT * INTO v_terms FROM public.partner_order_payment_terms
    WHERE id = NULLIF(v_gate->>'payment_terms_id','')::uuid
      AND partner_order_id = p_partner_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'payment_terms_not_canonical'; END IF;

  SELECT receivable_id INTO v_existing FROM public.partner_order_financial_links WHERE partner_order_id = p_partner_order_id;
  IF v_existing IS NOT NULL THEN
    INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
      VALUES (p_partner_order_id, v_order.partner_id, v_uid, 'financeiro_duplicidade_bloqueada', jsonb_build_object('receivable_id', v_existing));
    RETURN jsonb_build_object('receivable_id', v_existing, 'partner_order_id', p_partner_order_id, 'duplicado', true);
  END IF;

  SELECT * INTO v_partner FROM public.partner_accounts WHERE id = v_order.partner_id;
  SELECT * INTO v_settings FROM public.partner_financial_settings WHERE partner_id = v_order.partner_id;
  IF NOT FOUND THEN
    -- c2_ord_p1_no_provision: only the existing P1 CAS RPC creates settings.
    RAISE EXCEPTION 'B2B_FINANCIAL_SETTINGS_NOT_CONFIGURED' USING ERRCODE='P0001';
  END IF;

  -- External manual billing must honor configured delivery prerequisite too.
  IF v_order.c2_external_origin_snapshot IS NOT NULL AND v_settings.billing_trigger='na_entrega' AND v_order.status IS DISTINCT FROM 'entregue' THEN
    RAISE EXCEPTION 'C2_EXTERNAL_DELIVERY_REQUIRED' USING ERRCODE='42501';
  END IF;

  v_uf := to_jsonb(v_partner) ->> 'uf';

  -- Derivação fiscal (fail-closed; nunca NOT_REQUIRED silencioso)
  v_fiscal := public.fn_fiscal_requirement_resolve(
    'b2b_partner', 'venda_mercadoria', v_uf, 'partner_order', p_partner_order_id, CURRENT_DATE);

  -- c2_ord_strict_refs: financial_categories/payment_methods são catálogos globais por desenho (sem organization_id, RLS is_financial_staff; sem DDL de tenant
  -- no schema canônico); resolução estrita, sem fallback de tipo/inativo, falha explícita.
  SELECT id INTO v_category_id FROM public.financial_categories
   WHERE upper(btrim(type)) = 'RECEITA' AND active IS TRUE
   ORDER BY created_at ASC, id ASC LIMIT 1;
  IF v_category_id IS NULL THEN
    RAISE EXCEPTION 'B2B_REVENUE_CATEGORY_NOT_CONFIGURED' USING ERRCODE='P0001';
  END IF;
  IF NULLIF(btrim(COALESCE(v_settings.default_payment_method,'')),'') IS NULL THEN
    RAISE EXCEPTION 'B2B_PAYMENT_METHOD_NOT_CONFIGURED' USING ERRCODE='P0001';
  END IF;
  IF (SELECT count(*) FROM public.payment_methods pm
       WHERE pm.active IS TRUE AND lower(btrim(pm.name)) = lower(btrim(v_settings.default_payment_method))) <> 1 THEN
    RAISE EXCEPTION 'B2B_PAYMENT_METHOD_NOT_CONFIGURED' USING ERRCODE='P0001';
  END IF;
  SELECT pm.id INTO v_payment_method_id FROM public.payment_methods pm
   WHERE pm.active IS TRUE AND lower(btrim(pm.name)) = lower(btrim(v_settings.default_payment_method));
  IF v_partner.client_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.clientes cl WHERE cl.id = v_partner.client_id AND cl.organization_id = v_org) THEN
    RAISE EXCEPTION 'B2B_CUSTOMER_TENANT_MISMATCH' USING ERRCODE='42501';
  END IF;

  INSERT INTO public.accounts_receivable(
    organization_id, origin_type, origin_id, customer_id, partner_id, description,
    category_id, total_amount, issue_date, first_due_date, installment_count,
    status, fiscal_invoice_required, fiscal_invoice_status,
    fiscal_requirement_source, fiscal_policy_id, fiscal_exemption_id,
    payment_method_id, notes, created_by
  ) VALUES (
    v_org, 'B2B_ORDER', p_partner_order_id,
    NULLIF(v_partner.client_id, NULL), v_order.partner_id,
    format('Pedido B2B %s - %s', v_order.numero, COALESCE(v_partner.nome_fantasia, v_partner.razao_social)),
    v_category_id, v_terms.final_amount, CURRENT_DATE, v_terms.first_due_date, v_terms.installment_count,
    'OPEN',
    (v_fiscal->>'required')::boolean,
    v_fiscal->>'status',
    v_fiscal->>'source',
    NULLIF(v_fiscal->>'policy_id','')::uuid,
    NULLIF(v_fiscal->>'exemption_id','')::uuid,
    v_payment_method_id,
    format(E'Condição: %s (%s)\nDesconto: %s%%  Juros: %s%% a.m. x %s meses\nTabela: %s  Líquido: %s  Final: %s\nFiscal: %s (%s)',
           v_terms.plan_name_snapshot, v_terms.plan_code_snapshot,
           v_terms.discount_percent_snapshot, v_terms.monthly_interest_percent_snapshot, v_terms.months_count_snapshot,
           v_terms.table_amount, v_terms.net_amount_after_discount, v_terms.final_amount,
           v_fiscal->>'status', v_fiscal->>'source'),
    COALESCE(v_uid, v_order.created_by)
  ) RETURNING id INTO v_receivable_id;

  -- b2b_f1_fresh_title: no deletion; formal financial history protection preserved.

  FOR v_sch IN
    SELECT * FROM public.partner_order_payment_schedule
     WHERE partner_order_id = p_partner_order_id AND payment_terms_id = v_terms.id
     ORDER BY installment_number
  LOOP
    -- b2b_f1_reuse_installments: generic title trigger already created them.
    IF (SELECT count(*) FROM public.accounts_receivable_installments
         WHERE receivable_id=v_receivable_id AND installment_number=v_sch.installment_number
           AND organization_id=v_org) <> 1 THEN
      RAISE EXCEPTION 'B2B_INSTALLMENT_CARDINALITY_INVALID' USING ERRCODE='23514';
    END IF;
    UPDATE public.accounts_receivable_installments
       SET due_date=v_sch.due_date, original_amount=v_sch.amount,
           interest_amount=COALESCE(v_sch.interest_amount,0), net_amount=v_sch.amount
     WHERE receivable_id=v_receivable_id AND installment_number=v_sch.installment_number
       AND organization_id=v_org
     RETURNING id INTO v_ari_id;

    UPDATE public.partner_order_payment_schedule
       SET status = 'generated', receivable_installment_id = v_ari_id
     WHERE id = v_sch.id;

    v_installments_json := v_installments_json || jsonb_build_array(jsonb_build_object(
      'installment_number', v_sch.installment_number,
      'due_date', v_sch.due_date,
      'amount', v_sch.amount
    ));
  END LOOP;

  INSERT INTO public.partner_order_financial_links(
    partner_order_id, partner_id, receivable_id, financial_status, billing_trigger, created_by
  ) VALUES (
    p_partner_order_id, v_order.partner_id, v_receivable_id, 'gerado', v_settings.billing_trigger, v_uid
  );

  UPDATE public.partner_orders SET
    financial_status = 'gerado',
    receivable_generated = true,
    receivable_generated_at = now(),
    receivable_generated_by = v_uid,
    payment_due_date = v_terms.first_due_date,
    payment_method = COALESCE(v_settings.default_payment_method,'pix')
  WHERE id = p_partner_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (p_partner_order_id, v_order.partner_id, v_uid, 'financeiro_gerado_com_plano',
    jsonb_build_object(
      'receivable_id', v_receivable_id,
      'plan_code', v_terms.plan_code_snapshot,
      'plan_name', v_terms.plan_name_snapshot,
      'table_amount', v_terms.table_amount,
      'discount_amount', v_terms.discount_amount,
      'net_amount', v_terms.net_amount_after_discount,
      'interest_amount', v_terms.financial_interest_amount,
      'final_amount', v_terms.final_amount,
      'first_due_date', v_terms.first_due_date,
      'installment_count', v_terms.installment_count,
      'fiscal', v_fiscal,
      'gate', v_gate,
      'installments', v_installments_json
    ));

  RETURN jsonb_build_object(
    'receivable_id', v_receivable_id,
    'partner_order_id', p_partner_order_id,
    'valor', v_terms.final_amount,
    'vencimento', v_terms.first_due_date,
    'installment_count', v_terms.installment_count,
    'fiscal_invoice_required', (v_fiscal->>'required')::boolean,
    'fiscal_invoice_status', v_fiscal->>'status',
    'fiscal_requirement_source', v_fiscal->>'source',
    'status', 'OPEN'
  );
END 
$function$

CREATE OR REPLACE FUNCTION public.guard_tenant_organization_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_org uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;
  v_org := public.h15_actor_organization();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'tenant_context_required' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.organization_id IS NULL THEN
    NEW.organization_id := v_org;
  END IF;
  IF NEW.organization_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'tenant_scope_violation' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
    RAISE EXCEPTION 'tenant_immutable' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_estoque_movimentacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ctx jsonb := public.fn_estoque_ctx_read();
  v_acao text;
  v_dir text;
  v_usuario uuid;
  v_old_status text;
  v_new_status text;
  v_qtd numeric;
  v_mudou boolean;
  v_key text := v_ctx->>'idempotency_key';
  v_meta jsonb := COALESCE(v_ctx->'metadata', '{}'::jsonb);
  v_seq int;
BEGIN
  -- Uma operação do motor pode tocar mais de uma linha (reserva parcial).
  -- O lançamento principal fica com a chave da operação; os complementares
  -- recebem chave derivada determinística e são marcados como desdobramento.
  IF v_key IS NOT NULL THEN
    SELECT count(*) INTO v_seq
      FROM public.estoque_movimentacoes
     WHERE idempotency_key = v_key OR left(idempotency_key,length(v_key)+1) = v_key || '#';
    IF v_seq > 0 THEN
      v_meta := v_meta || jsonb_build_object('desdobramento', true, 'operacao_key', v_key);
      v_key := v_key || '#' || v_seq::text;
    END IF;
  END IF;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.estoque_movimentacoes
      (estoque_produto_id, acao, quantidade, status_novo, lote_id, usuario_id,
       saldo_anterior, saldo_posterior, reservado_anterior, reservado_posterior,
       volume_anterior, volume_posterior, unidade, direcao,
       origem, referencia_tipo, referencia_id, motivo, idempotency_key, request_fingerprint,
       movimentacao_origem_id, os_id, os_tipo, cliente_id, metadata)
    VALUES (
      NEW.id,
      COALESCE(v_ctx->>'acao', 'entrada'),
      NULLIF(NEW.quantidade, 0), NEW.status::text, NEW.lote_id,
      COALESCE(auth.uid(), (v_ctx->>'usuario_id')::uuid),
      0, COALESCE(NEW.quantidade, 0),
      0, COALESCE(NEW.quantidade_reservada, 0),
      0, COALESCE(NEW.volume_total, 0),
      COALESCE(v_ctx->>'unidade', 'un'), 'entrada',
      COALESCE(v_ctx->>'origem', 'trigger'),
      v_ctx->>'referencia_tipo', (v_ctx->>'referencia_id')::uuid,
      v_ctx->>'motivo', v_key, v_ctx->>'request_fingerprint',
      (v_ctx->>'movimentacao_origem_id')::uuid,
      NEW.reservado_para_os_id, NEW.reservado_para_os_tipo, NEW.reservado_para_cliente_id,
      v_meta
    );
    RETURN NEW;
  END IF;

  v_mudou := (OLD.status IS DISTINCT FROM NEW.status)
          OR (COALESCE(OLD.quantidade,0) IS DISTINCT FROM COALESCE(NEW.quantidade,0))
          OR (COALESCE(OLD.quantidade_reservada,0) IS DISTINCT FROM COALESCE(NEW.quantidade_reservada,0))
          OR (COALESCE(OLD.volume_total,0) IS DISTINCT FROM COALESCE(NEW.volume_total,0));
  IF NOT v_mudou THEN RETURN NEW; END IF;

  v_old_status := OLD.status::text;
  v_new_status := NEW.status::text;

  v_acao := COALESCE(v_ctx->>'acao', CASE
    WHEN v_new_status = 'reservado'  AND v_old_status = 'expedido'  THEN 'estorno_expedicao'
    WHEN v_new_status = 'reservado'  AND v_old_status <> 'reservado' THEN 'reserva'
    WHEN v_new_status = 'expedido'   AND v_old_status <> 'expedido'  THEN 'expedicao'
    WHEN v_new_status = 'estornado'                                  THEN 'estorno_expedicao'
    WHEN v_old_status = 'reservado'  AND v_new_status = 'disponivel' THEN 'cancelamento_reserva'
    WHEN v_old_status = v_new_status THEN 'ajuste'
    ELSE 'edicao'
  END);

  v_dir := COALESCE(v_ctx->>'direcao', CASE
    WHEN COALESCE(NEW.quantidade,0) > COALESCE(OLD.quantidade,0) THEN 'entrada'
    WHEN COALESCE(NEW.quantidade,0) < COALESCE(OLD.quantidade,0) THEN 'saida'
    WHEN v_acao IN ('expedicao','descarte','perda','consumo','entrega') THEN 'saida'
    WHEN v_acao IN ('estorno_expedicao','devolucao') THEN 'entrada'
    ELSE 'neutro'
  END);

  v_usuario := COALESCE(auth.uid(), (v_ctx->>'usuario_id')::uuid,
    CASE WHEN v_new_status = 'expedido' THEN NEW.expedido_por ELSE NEW.reservado_por END);

  v_qtd := NULLIF(ABS(COALESCE(NEW.quantidade,0) - COALESCE(OLD.quantidade,0)), 0);
  IF v_qtd IS NULL THEN
    v_qtd := NULLIF(ABS(COALESCE(NEW.quantidade_reservada,0) - COALESCE(OLD.quantidade_reservada,0)), 0);
  END IF;
  IF v_qtd IS NULL THEN
    v_qtd := NULLIF(COALESCE(NEW.quantidade_reservada, NEW.quantidade, 0), 0);
  END IF;

  INSERT INTO public.estoque_movimentacoes
    (estoque_produto_id, acao, quantidade, status_anterior, status_novo,
     os_id, os_tipo, cliente_id, lote_id, usuario_id, observacao,
     saldo_anterior, saldo_posterior, reservado_anterior, reservado_posterior,
     volume_anterior, volume_posterior, unidade, direcao,
     origem, referencia_tipo, referencia_id, motivo,
     idempotency_key, request_fingerprint, movimentacao_origem_id, metadata)
  VALUES (
    NEW.id, v_acao, v_qtd, v_old_status, v_new_status,
    NEW.reservado_para_os_id, NEW.reservado_para_os_tipo, NEW.reservado_para_cliente_id,
    NEW.lote_id, v_usuario, COALESCE(v_ctx->>'observacao', NEW.observacao_reserva),
    COALESCE(OLD.quantidade,0), COALESCE(NEW.quantidade,0),
    COALESCE(OLD.quantidade_reservada,0), COALESCE(NEW.quantidade_reservada,0),
    COALESCE(OLD.volume_total,0), COALESCE(NEW.volume_total,0),
    COALESCE(v_ctx->>'unidade','un'), v_dir,
    COALESCE(v_ctx->>'origem','trigger'),
    v_ctx->>'referencia_tipo', (v_ctx->>'referencia_id')::uuid, v_ctx->>'motivo',
    v_key, v_ctx->>'request_fingerprint',
    (v_ctx->>'movimentacao_origem_id')::uuid,
    v_meta
  );

  IF v_acao = 'reserva' THEN
    INSERT INTO public.notificacoes_operacionais (usuario_id, tipo, titulo, mensagem, link)
    SELECT ur.user_id, 'nova_reserva', 'Nova reserva de estoque',
           'Item reservado aguardando expedição.', '/estoque'
      FROM public.user_roles ur JOIN public.profiles pr ON pr.user_id=ur.user_id AND pr.ativo IS TRUE JOIN public.lotes l ON l.id=NEW.lote_id AND l.organization_id=pr.organization_id JOIN public.organizations o ON o.id=pr.organization_id AND o.ativo IS TRUE WHERE ur.role = 'administrativo'::app_role AND l.organization_id IS NOT NULL;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.partner_orders_audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_acao text;
  v_old jsonb;
  v_new jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_acao := 'order_created';
    v_new := to_jsonb(NEW);
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := to_jsonb(OLD);
    v_new := to_jsonb(NEW);
    IF OLD.status IS DISTINCT FROM NEW.status THEN
      v_acao := CASE WHEN NEW.status = 'cancelado' THEN 'order_cancelled' ELSE 'status_changed' END;
    ELSE
      v_acao := 'order_updated';
    END IF;
  ELSE
    RETURN NULL;
  END IF;
  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (COALESCE(NEW.id, OLD.id), COALESCE(NEW.partner_id, OLD.partner_id), auth.uid(), v_acao, v_old, v_new);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.recalc_partner_order_production(p_partner_order_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_planning_id   uuid;
  v_partner_id    uuid;
  v_numero        text;
  v_total         int;
  v_em_producao   int;
  v_produzidos    int;
  v_entregues     int;
  v_new_status    production_planning_status;
  v_old_status    production_planning_status;
BEGIN
  SELECT pp.id, pp.status, po.partner_id, po.numero
    INTO v_planning_id, v_old_status, v_partner_id, v_numero
  FROM public.production_planning pp
  JOIN public.partner_orders     po ON po.id = pp.partner_order_id
  WHERE pp.partner_order_id = p_partner_order_id;

  IF v_planning_id IS NULL THEN
    RETURN;
  END IF;

  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE os.status IN ('em_producao','em_cq','envase','pronto_entrega','entregue','finalizada')),
    COUNT(*) FILTER (WHERE os.status IN ('pronto_entrega','entregue','finalizada')),
    COUNT(*) FILTER (WHERE os.status IN ('entregue','finalizada'))
  INTO v_total, v_em_producao, v_produzidos, v_entregues
  FROM public.production_order_link l
  JOIN public.ordens_servico os ON os.id = l.ordem_servico_id
  WHERE l.partner_order_id = p_partner_order_id;

  IF v_total = 0 THEN
    v_new_status := 'aguardando_planejamento';
  ELSIF v_entregues = v_total THEN
    v_new_status := 'entregue';
  ELSIF v_produzidos = v_total THEN
    v_new_status := 'produzido';
  ELSIF v_em_producao > 0 THEN
    v_new_status := 'em_producao';
  ELSE
    v_new_status := 'planejado';
  END IF;

  IF v_new_status IS DISTINCT FROM v_old_status THEN
    UPDATE public.production_planning
       SET status = v_new_status,
           updated_at = now()
     WHERE id = v_planning_id;

    INSERT INTO public.production_timeline_events (partner_order_id, event_type, meta)
    VALUES (
      p_partner_order_id,
      CASE v_new_status
        WHEN 'planejado'   THEN 'op_gerada'
        WHEN 'em_producao' THEN 'producao_iniciada'
        WHEN 'produzido'   THEN 'producao_finalizada'
        WHEN 'entregue'    THEN 'entrega_realizada'
        ELSE 'status_alterado'
      END,
      jsonb_build_object(
        'from', v_old_status::text,
        'to',   v_new_status::text,
        'total_ops', v_total,
        'em_producao', v_em_producao,
        'produzidos', v_produzidos,
        'entregues', v_entregues
      )
    );

    IF v_new_status IN ('em_producao','produzido','entregue') THEN
      INSERT INTO public.notificacoes_operacionais (usuario_id, tipo, titulo, mensagem, link)
      SELECT pu.user_id,
             'pedido_b2b',
             CASE v_new_status
               WHEN 'em_producao' THEN 'Pedido ' || v_numero || ' em produção'
               WHEN 'produzido'   THEN 'Pedido ' || v_numero || ' pronto para expedição'
               WHEN 'entregue'    THEN 'Pedido ' || v_numero || ' entregue'
             END,
             CASE v_new_status
               WHEN 'em_producao' THEN 'A produção do seu pedido foi iniciada.'
               WHEN 'produzido'   THEN 'Produção concluída. Aguardando envase e expedição.'
               WHEN 'entregue'    THEN 'Seu pedido foi entregue.'
             END,
             '/portal-parceiro/pedidos'
        FROM public.partner_users pu
       WHERE pu.partner_id = v_partner_id;
    END IF;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.recalc_partner_risk_score(p_partner_id uuid)
 RETURNS partner_risk_scores
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_dias_atraso numeric := 0;
  v_vencidos int := 0;
  v_pct numeric := 0;
  v_freq int := 0;
  v_meses int := 0;
  v_limite numeric := 0;
  v_aberto numeric := 0;
  v_score int := 0;
  v_level text := 'baixo';
  v_row public.partner_risk_scores;
BEGIN
  -- H7O: dentro de trigger (pg_trigger_depth()>0) ou sessão interna (sem JWT) segue livre;
  -- chamada autenticada direta exige staff financeiro.
  IF pg_trigger_depth() = 0 AND auth.uid() IS NOT NULL AND NOT public.is_financial_staff(auth.uid()) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501',
      HINT = 'H7O: recálculo de score de risco restrito ao staff financeiro.';
  END IF;

  IF p_partner_id IS NULL THEN RAISE EXCEPTION 'partner_id required'; END IF;

  SELECT COALESCE(AVG(GREATEST(0, CURRENT_DATE - ari.due_date)),0)::numeric,
         COUNT(*) FILTER (WHERE ari.status='OVERDUE' OR (ari.status IN ('OPEN','PARTIAL') AND ari.due_date < CURRENT_DATE))
    INTO v_dias_atraso, v_vencidos
  FROM accounts_receivable ar
  JOIN accounts_receivable_installments ari ON ari.receivable_id = ar.id
  WHERE ar.origin_type='B2B_ORDER' AND ar.partner_id = p_partner_id
    AND ari.status IN ('OPEN','PARTIAL','OVERDUE');

  SELECT COALESCE(credit_limit,0) INTO v_limite FROM partner_financial_settings WHERE partner_id = p_partner_id;
  v_limite := COALESCE(v_limite,0);

  SELECT COALESCE(SUM(ari.original_amount - ari.received_amount),0) INTO v_aberto
  FROM accounts_receivable ar
  JOIN accounts_receivable_installments ari ON ari.receivable_id = ar.id
  WHERE ar.origin_type='B2B_ORDER' AND ar.partner_id = p_partner_id
    AND ari.status IN ('OPEN','PARTIAL','OVERDUE');

  v_pct := CASE WHEN v_limite > 0 THEN LEAST(100,(v_aberto/v_limite)*100) ELSE 0 END;

  SELECT COUNT(*) INTO v_freq FROM partner_orders
   WHERE partner_id = p_partner_id AND created_at >= now() - interval '30 days'
     AND status NOT IN ('cancelado','reprovado');

  SELECT GREATEST(0, EXTRACT(YEAR FROM age(now(), pa.created_at))*12 + EXTRACT(MONTH FROM age(now(), pa.created_at)))::int
    INTO v_meses FROM partner_accounts pa WHERE id = p_partner_id;

  -- score (peso): atraso 35, vencidos 25, util 20, freq -10, relacionamento -10
  v_score := LEAST(100, GREATEST(0,
      ROUND(LEAST(v_dias_atraso/90.0,1)*35)
    + ROUND(LEAST(v_vencidos/5.0,1)*25)
    + ROUND((v_pct/100.0)*20)
    - ROUND(LEAST(v_freq/10.0,1)*10)
    - ROUND(LEAST(COALESCE(v_meses,0)/24.0,1)*10)
  ));
  v_level := CASE
    WHEN v_score <= 30 THEN 'baixo'
    WHEN v_score <= 60 THEN 'medio'
    WHEN v_score <= 80 THEN 'alto'
    ELSE 'critico' END;

  INSERT INTO partner_risk_scores (partner_id, score, risk_level, dias_medio_atraso, titulos_vencidos, pct_credito_utilizado, freq_compras_30d, meses_relacionamento, calculado_em)
  VALUES (p_partner_id, v_score, v_level, v_dias_atraso, v_vencidos, v_pct, v_freq, COALESCE(v_meses,0), now())
  ON CONFLICT (partner_id) DO UPDATE SET
    score = EXCLUDED.score,
    risk_level = EXCLUDED.risk_level,
    dias_medio_atraso = EXCLUDED.dias_medio_atraso,
    titulos_vencidos = EXCLUDED.titulos_vencidos,
    pct_credito_utilizado = EXCLUDED.pct_credito_utilizado,
    freq_compras_30d = EXCLUDED.freq_compras_30d,
    meses_relacionamento = EXCLUDED.meses_relacionamento,
    calculado_em = now()
  RETURNING * INTO v_row;

  INSERT INTO financial_governance_audit_log(usuario_id, partner_id, acao, dados_novos)
  VALUES (auth.uid(), p_partner_id, 'score_recalculado', to_jsonb(v_row));

  RETURN v_row;
END;$function$

CREATE OR REPLACE FUNCTION public.reservar_estoque_item(p_item_id uuid, p_qty numeric, p_os_id uuid, p_os_tipo text, p_cliente_id uuid DEFAULT NULL::uuid, p_partner_id uuid DEFAULT NULL::uuid, p_partner_order_id uuid DEFAULT NULL::uuid, p_observacao text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item public.estoque_produto%ROWTYPE;
  v_volume_reservado numeric;
  v_new_id uuid;
  v_parent_ctx jsonb;
BEGIN
  PERFORM platform_private.stock_motor_actor('reserva');
  IF p_qty IS NULL OR p_qty::text IN ('NaN','Infinity','-Infinity') OR p_qty <= 0 THEN
    RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA: quantidade deve ser finita e maior que zero.' USING ERRCODE='23514';
  END IF;
  PERFORM platform_private.stock_motor_item(p_item_id,'reserva',jsonb_build_object('os_id',p_os_id,'os_tipo',p_os_tipo,'cliente_id',p_cliente_id,'partner_id',p_partner_id,'partner_order_id',p_partner_order_id));
  IF auth.uid() IS NULL OR NOT public.fn_estoque_pode_operar(auth.uid(), 'reserva') THEN
    RAISE EXCEPTION 'ESTQ_SEM_PERMISSAO: perfil sem permissão para reservar estoque'
      USING ERRCODE = '42501';
  END IF;

  SELECT c.ctx INTO v_parent_ctx FROM platform_private.stock_motor_context c WHERE c.txid=txid_current() AND c.actor=auth.uid() AND c.item=p_item_id;
  IF v_parent_ctx IS NOT NULL AND (v_parent_ctx->>'acao' IS DISTINCT FROM 'reserva' OR v_parent_ctx->'reserve_args' IS DISTINCT FROM jsonb_strip_nulls(jsonb_build_object('os_id',p_os_id::text,'os_tipo',p_os_tipo,'cliente_id',p_cliente_id::text,'partner_id',p_partner_id::text,'partner_order_id',p_partner_order_id::text,'observacao',p_observacao))) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  IF v_parent_ctx IS NULL THEN
   v_parent_ctx:=jsonb_build_object('acao','reserva','origem','reservar_estoque_item','usuario_id',auth.uid()::text,'metadata',jsonb_build_object('stock_request_item',p_item_id::text,'stock_request_actor',auth.uid()::text));
  END IF;
  PERFORM public.fn_estoque_ctx_force(v_parent_ctx);
  IF p_qty IS NULL OR p_qty <= 0 THEN
    RAISE EXCEPTION 'Quantidade a reservar deve ser maior que zero.'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_os_id IS NULL THEN
    RAISE EXCEPTION 'Reserva requer uma OS vinculada.'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_item
  FROM public.estoque_produto
  WHERE id = p_item_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Item de estoque % não encontrado.', p_item_id
      USING ERRCODE = 'no_data_found';
  END IF;

  PERFORM platform_private.stock_motor_item(p_item_id,'reserva',jsonb_build_object('os_id',p_os_id,'os_tipo',p_os_tipo,'cliente_id',p_cliente_id,'partner_id',p_partner_id,'partner_order_id',p_partner_order_id));
  IF v_item.status::text <> 'disponivel' THEN
    RAISE EXCEPTION 'Item % não está disponível para reserva (status: %).', p_item_id, v_item.status
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_qty > COALESCE(v_item.quantidade, 0) THEN
    RAISE EXCEPTION 'Quantidade solicitada (%) excede o disponível (%) para esta embalagem.',
      p_qty, COALESCE(v_item.quantidade, 0)
      USING ERRCODE = 'check_violation';
  END IF;

  v_volume_reservado := CASE
    WHEN COALESCE(v_item.volume_total, 0) > 0 AND COALESCE(v_item.quantidade, 0) > 0
      THEN (p_qty * v_item.volume_total) / v_item.quantidade
    ELSE NULL
  END;

  IF p_qty = v_item.quantidade THEN
    UPDATE public.estoque_produto SET
      status = 'reservado',
      reservado_para_os_id = p_os_id,
      reservado_para_os_tipo = p_os_tipo,
      reservado_para_cliente_id = CASE WHEN p_os_tipo = 'b2b' THEN NULL ELSE p_cliente_id END,
      reservado_para_partner_id = CASE WHEN p_os_tipo = 'b2b' THEN p_partner_id ELSE NULL END,
      reservado_para_partner_order_id = CASE WHEN p_os_tipo = 'b2b' THEN p_partner_order_id ELSE NULL END,
      quantidade_reservada = p_qty,
      observacao_reserva = p_observacao
    WHERE id = p_item_id;
    v_new_id := p_item_id;
  ELSE
    INSERT INTO public.estoque_produto (
      produto_id, lote_id, microrganismo_id, envase_id,
      quantidade, volume_total, validade, status,
      reservado_para_os_id, reservado_para_os_tipo,
      reservado_para_cliente_id, reservado_para_partner_id, reservado_para_partner_order_id,
      quantidade_reservada, observacao_reserva
    ) VALUES (
      v_item.produto_id, v_item.lote_id, v_item.microrganismo_id, v_item.envase_id,
      p_qty, v_volume_reservado, v_item.validade, 'reservado',
      p_os_id, p_os_tipo,
      CASE WHEN p_os_tipo = 'b2b' THEN NULL ELSE p_cliente_id END,
      CASE WHEN p_os_tipo = 'b2b' THEN p_partner_id ELSE NULL END,
      CASE WHEN p_os_tipo = 'b2b' THEN p_partner_order_id ELSE NULL END,
      p_qty, p_observacao
    ) RETURNING id INTO v_new_id;

    UPDATE public.estoque_produto SET
      quantidade = v_item.quantidade - p_qty,
      volume_total = CASE
        WHEN COALESCE(v_item.volume_total, 0) > 0 THEN v_item.volume_total - v_volume_reservado
        ELSE volume_total
      END
    WHERE id = p_item_id;
  END IF;

  PERFORM platform_private.stock_motor_context_set(NULL); PERFORM public.fn_estoque_ctx_close();
  RETURN v_new_id;
EXCEPTION WHEN OTHERS THEN PERFORM platform_private.stock_motor_context_set(NULL); PERFORM public.fn_estoque_ctx_close(); RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_cockpit_cancelar_reserva_v1(p_item_id uuid, p_os_id uuid, p_origem text, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_origem text;
  v_item public.estoque_produto%ROWTYPE;
  v_main public.estoque_produto%ROWTYPE;
  v_modo text;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
BEGIN
  PERFORM public.fn_estoque_ctx_open(jsonb_build_object('acao','cancelamento_reserva','origem','rpc_cockpit_cancelar_reserva_v1','usuario_id',auth.uid()::text));
  v_origem := public.fn_cockpit_assert_operador_origem(p_origem);

  IF p_item_id IS NULL OR p_os_id IS NULL THEN RAISE EXCEPTION 'COCKPIT_RESERVA_PARAMS_INVALIDOS'; END IF;
  IF v_motivo IS NULL THEN RAISE EXCEPTION 'COCKPIT_RESERVA_MOTIVO_OBRIGATORIO'; END IF;

  PERFORM pg_advisory_xact_lock(hashtext('cockpit_reserva:' || p_item_id::text));

  SELECT * INTO v_item FROM public.estoque_produto WHERE id = p_item_id FOR UPDATE;
  IF v_item.id IS NULL THEN RAISE EXCEPTION 'COCKPIT_RESERVA_NAO_ENCONTRADA'; END IF;

  IF v_item.status::text = 'estornado' OR v_item.quantidade_reservada IS NULL THEN
    RETURN jsonb_build_object('success', true, 'replay', true,
      'message', 'Reserva já cancelada anteriormente.');
  END IF;
  IF v_item.status::text = 'expedido' THEN RAISE EXCEPTION 'COCKPIT_RESERVA_JA_EXPEDIDA'; END IF;

  -- coerência: a reserva precisa pertencer à MESMA OS/origem
  IF v_item.reservado_para_os_id IS DISTINCT FROM p_os_id THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_RESERVA_OS';
  END IF;
  IF coalesce(v_item.reservado_para_os_tipo, v_origem) IS DISTINCT FROM v_origem THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_RESERVA_ORIGEM';
  END IF;

  -- override (cancelar reserva feita por outro operador) exige gestor
  IF v_item.reservado_por IS DISTINCT FROM v_uid AND NOT public.fn_cockpit_is_gestor() THEN
    RAISE EXCEPTION 'COCKPIT_RESERVA_OVERRIDE_SEM_ALCADA';
  END IF;

  -- saldo principal compatível (mesmo lote, envase, item e validade)
  SELECT * INTO v_main
    FROM public.estoque_produto
   WHERE lote_id = v_item.lote_id
     AND envase_id IS NOT DISTINCT FROM v_item.envase_id
     AND produto_id IS NOT DISTINCT FROM v_item.produto_id
     AND microrganismo_id IS NOT DISTINCT FROM v_item.microrganismo_id
     AND validade IS NOT DISTINCT FROM v_item.validade
     AND quantidade_reservada IS NULL
     AND status = 'disponivel'::public.status_estoque
     AND id <> v_item.id
   ORDER BY id LIMIT 1 FOR UPDATE;

  IF v_main.id IS NOT NULL THEN
    v_modo := 'estorno_para_saldo_principal';
    UPDATE public.estoque_produto
       SET quantidade = coalesce(v_main.quantidade,0) + coalesce(v_item.quantidade,0),
           volume_total = coalesce(v_main.volume_total,0) + coalesce(v_item.volume_total,0),
           updated_at = now()
     WHERE id = v_main.id;

    UPDATE public.estoque_produto
       SET status = 'estornado'::public.status_estoque, quantidade = 0, volume_total = 0,
           quantidade_reservada = 0, reservado_para_os_id = NULL, reservado_para_os_tipo = NULL,
           reservado_para_cliente_id = NULL, reservado_para_partner_id = NULL,
           reservado_para_partner_order_id = NULL,
           observacao_reserva = v_motivo || format(' — saldo devolvido ao registro %s', v_main.id),
           updated_at = now()
     WHERE id = v_item.id;

  ELSE
    v_modo := 'liberacao_no_proprio_registro';
    UPDATE public.estoque_produto
       SET status = 'disponivel'::public.status_estoque, quantidade_reservada = NULL,
           reservado_para_os_id = NULL, reservado_para_os_tipo = NULL,
           reservado_para_cliente_id = NULL, reservado_para_partner_id = NULL,
           reservado_para_partner_order_id = NULL,
           observacao_reserva = v_motivo, updated_at = now()
     WHERE id = v_item.id;

  END IF;

  INSERT INTO public.laboratorio_esteira_eventos
    (os_id, origem_os, lote_id, etapa_anterior, etapa_nova, acao, usuario_id, observacao)
  VALUES (p_os_id, v_origem, v_item.lote_id, 'estoque_reservado', 'estoque_disponivel',
          'cancelar_reserva_v1', v_uid, format('Cancelamento transacional (%s). Motivo: %s', v_modo, v_motivo));

  RETURN jsonb_build_object('success', true, 'replay', false, 'modo', v_modo,
    'message', 'Reserva cancelada e saldo devolvido em transação única.');
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_cockpit_criar_entrega_v1(p_os_id uuid, p_origem text, p_estoque_produto_id uuid, p_quantidade numeric, p_dados jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_origem text;
  v_est public.estoque_produto%ROWTYPE;
  v_existente record;
  v_id uuid;
  v_cliente_os uuid;
BEGIN
  v_origem := public.fn_cockpit_assert_operador_origem(p_origem);

  IF p_os_id IS NULL OR p_estoque_produto_id IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_PARAMS_INVALIDOS';
  END IF;
  IF coalesce(p_quantidade, 0) <= 0 THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_QUANTIDADE_INVALIDA';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('cockpit_criar_entrega:' || p_os_id::text || ':' || p_estoque_produto_id::text));

  SELECT * INTO v_est
  FROM public.estoque_produto
  WHERE id = p_estoque_produto_id
  FOR UPDATE;

  IF v_est.id IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_ESTOQUE_NAO_ENCONTRADO';
  END IF;

  IF v_origem = 'onfarm' THEN
    SELECT cliente_id INTO v_cliente_os
    FROM public.ordens_servico_onfarm
    WHERE id = p_os_id;
  ELSE
    SELECT cliente_id INTO v_cliente_os
    FROM public.ordens_servico
    WHERE id = p_os_id;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_OS_NAO_ENCONTRADA';
  END IF;

  IF v_est.status::text NOT IN ('reservado', 'expedido') THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_STATUS_ESTOQUE_INVALIDO';
  END IF;
  IF v_est.reservado_para_os_id IS DISTINCT FROM p_os_id THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_ESTOQUE';
  END IF;
  IF coalesce(v_est.reservado_para_os_tipo, v_origem) IS DISTINCT FROM v_origem THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_ORIGEM';
  END IF;
  IF p_quantidade > coalesce(v_est.quantidade, 0) THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_QUANTIDADE_EXCEDE_RESERVA';
  END IF;
  IF v_est.reservado_para_cliente_id IS NOT NULL
     AND v_est.reservado_para_cliente_id IS DISTINCT FROM v_cliente_os THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_CLIENTE';
  END IF;
  IF nullif(p_dados->>'cliente_id','') IS NOT NULL
     AND nullif(p_dados->>'cliente_id','')::uuid IS DISTINCT FROM v_cliente_os THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_CLIENTE';
  END IF;

  SELECT e.id, e.status::text AS status INTO v_existente
  FROM public.entregas e
  WHERE e.estoque_produto_id = p_estoque_produto_id
    AND e.status::text <> 'cancelada'
    AND (
      (v_origem = 'onfarm' AND e.ordem_servico_onfarm_id = p_os_id)
      OR (v_origem <> 'onfarm' AND e.ordem_servico_id = p_os_id)
    )
  ORDER BY e.created_at DESC
  LIMIT 1;

  IF v_existente.id IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'replay', true, 'entrega_id', v_existente.id, 'status', v_existente.status, 'message', 'Entrega ja registrada para este item da OS.');
  END IF;


  IF coalesce(nullif(p_dados->>'tipo_entrega',''), 'motorista') NOT IN ('motorista','retirada') THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_MODALIDADE_INVALIDA';
  END IF;
  IF coalesce(nullif(p_dados->>'endereco_origem',''), 'cadastro') NOT IN ('cadastro','personalizado') THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_ENDERECO_ORIGEM_INVALIDA';
  END IF;
  IF v_est.volume_total IS NULL OR v_est.volume_total <= 0 OR v_est.volume_total::text IN ('NaN','Infinity','-Infinity')
     OR v_est.quantidade IS NULL OR v_est.quantidade <= 0 THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_VOLUME_ESTOQUE_INVALIDO';
  END IF;

  INSERT INTO public.entregas (
    ordem_servico_id, ordem_servico_onfarm_id, estoque_produto_id,
    lote_id, produto_id, quantidade_entregue, status, cliente_id,
    data_saida, motorista, veiculo
  ) VALUES (
    CASE WHEN v_origem = 'onfarm' THEN NULL ELSE p_os_id END,
    CASE WHEN v_origem = 'onfarm' THEN p_os_id ELSE NULL END,
    p_estoque_produto_id,
    v_est.lote_id,
    v_est.produto_id,
    p_quantidade,
    'separado'::public.status_entrega,
    v_cliente_os,
    nullif(p_dados->>'data_saida','')::date,
    nullif(p_dados->>'motorista',''),
    nullif(p_dados->>'veiculo','')
  ) RETURNING id INTO v_id;


  -- Only newly created delivery: preserve replay semantics and never overwrite existing history.
  UPDATE public.entregas SET
    volume_entregue_ml = round((v_est.volume_total / v_est.quantidade) * p_quantidade * 1000, 6),
    tipo_entrega = coalesce(nullif(p_dados->>'tipo_entrega',''), 'motorista'),
    endereco_origem = coalesce(nullif(p_dados->>'endereco_origem',''), 'cadastro'),
    grupo_entrega_id = nullif(p_dados->>'grupo_entrega_id','')::uuid,
    hora_saida_prevista = nullif(p_dados->>'hora_saida_prevista','')::time,
    data_chegada_prevista = nullif(p_dados->>'data_chegada_prevista','')::date,
    hora_chegada_prevista = nullif(p_dados->>'hora_chegada_prevista','')::time,
    motorista_telefone = nullif(p_dados->>'motorista_telefone',''),
    motorista_documento = nullif(p_dados->>'motorista_documento',''),
    veiculo_placa = nullif(p_dados->>'veiculo_placa',''),
    veiculo_tipo = nullif(p_dados->>'veiculo_tipo',''),
    destinatario_nome = nullif(p_dados->>'destinatario_nome',''),
    destinatario_telefone = nullif(p_dados->>'destinatario_telefone',''),
    destinatario_whatsapp = nullif(p_dados->>'destinatario_whatsapp',''),
    endereco_logradouro = nullif(p_dados->>'endereco_logradouro',''),
    endereco_numero = nullif(p_dados->>'endereco_numero',''),
    endereco_complemento = nullif(p_dados->>'endereco_complemento',''),
    endereco_bairro = nullif(p_dados->>'endereco_bairro',''),
    endereco_cidade = nullif(p_dados->>'endereco_cidade',''),
    endereco_uf = nullif(p_dados->>'endereco_uf',''),
    endereco_cep = nullif(p_dados->>'endereco_cep',''),
    endereco_referencia = nullif(p_dados->>'endereco_referencia','')
  WHERE id = v_id;

  INSERT INTO public.laboratorio_esteira_eventos
    (os_id, origem_os, etapa_nova, acao, usuario_id, observacao)
  VALUES
    (p_os_id, v_origem, 'entrega_criada', 'criar_entrega_v1', v_uid,
     format('Entrega %s criada (motor transacional).', v_id));

  RETURN jsonb_build_object('success', true, 'replay', false, 'entrega_id', v_id, 'status', 'separado', 'message', 'Entrega registrada. Confirme a entrega para concluir a OS.');
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_cockpit_criar_entrega_v1(p_os_id uuid, p_origem text, p_itens jsonb, p_request_key text, p_dados jsonb, p_os_observed timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '3s'
AS $function$
DECLARE v_org uuid; v_actor uuid:=auth.uid(); v_os public.ordens_servico%ROWTYPE;
 v_item jsonb; v_id uuid; v_qty numeric; v_items jsonb:='[]'; v_fp text;
 v_prev platform_private.delivery_requests_20261030%ROWTYPE; v_batch jsonb; v_call jsonb;
 v_result jsonb:='[]'; v_index integer:=0; v_ent uuid; v_reserved uuid; v_current timestamptz; v_original_client uuid;
BEGIN
 v_org:=platform_private.delivery_actor_20261030('group');
 IF p_origem IS DISTINCT FROM 'manual' OR p_os_id IS NULL THEN RAISE EXCEPTION 'DELIVERY_ORIGIN_CLOSED' USING ERRCODE='42501'; END IF;
 IF p_os_observed IS NULL THEN RAISE EXCEPTION 'DELIVERY_OBSERVED_REQUIRED' USING ERRCODE='22023'; END IF;
 IF p_request_key IS NULL OR length(btrim(p_request_key))<8 OR length(p_request_key)>128 THEN RAISE EXCEPTION 'DELIVERY_REQUEST_INVALID' USING ERRCODE='22023'; END IF;
 IF p_dados IS NULL OR jsonb_typeof(p_dados)<>'object' OR EXISTS(SELECT 1 FROM jsonb_each(p_dados) WHERE key NOT IN ('data_saida','motorista','veiculo','tipo_entrega','endereco_origem') OR jsonb_typeof(value) NOT IN ('string','null')) THEN RAISE EXCEPTION 'DELIVERY_DATA_INVALID' USING ERRCODE='22023'; END IF;
 IF p_itens IS NULL OR jsonb_typeof(p_itens)<>'array' THEN RAISE EXCEPTION 'DELIVERY_ITEMS_INVALID' USING ERRCODE='22023'; END IF;
 IF jsonb_array_length(p_itens)=0 OR jsonb_array_length(p_itens)>100 THEN RAISE EXCEPTION 'DELIVERY_ITEMS_INVALID' USING ERRCODE='22023'; END IF;
 SELECT * INTO v_os FROM public.ordens_servico WHERE id=p_os_id AND organization_id=v_org;
 IF NOT FOUND OR v_os.partner_order_id IS NOT NULL OR v_os.origem IS DISTINCT FROM 'agronomica' THEN RAISE EXCEPTION 'DELIVERY_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF v_os.updated_at IS DISTINCT FROM p_os_observed THEN RAISE EXCEPTION 'DELIVERY_OBSERVED_CONFLICT' USING ERRCODE='PT409'; END IF;
 v_original_client:=v_os.cliente_id;
 FOR v_item IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
  IF jsonb_typeof(v_item)<>'object' OR NOT(v_item ? 'item_id' AND v_item ? 'quantidade' AND v_item ? 'observed_updated_at') OR v_item->>'observed_updated_at' IS NULL OR EXISTS(SELECT 1 FROM jsonb_each(v_item) WHERE key NOT IN ('item_id','quantidade','observed_updated_at')) THEN RAISE EXCEPTION 'DELIVERY_ITEMS_INVALID' USING ERRCODE='22023'; END IF;
  v_id:=(v_item->>'item_id')::uuid; v_qty:=(v_item->>'quantidade')::numeric;
  IF v_id IS NULL OR v_qty IS NULL OR v_qty<=0 OR v_qty::text IN ('NaN','Infinity','-Infinity') OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_items) WHERE value->>'item_id'=v_id::text) THEN RAISE EXCEPTION 'DELIVERY_ITEMS_INVALID' USING ERRCODE='22023'; END IF;
  v_items:=v_items||jsonb_build_array(jsonb_build_object('item_id',v_id,'quantidade',v_qty,'observed_updated_at',(v_item->>'observed_updated_at')::timestamptz));
 END LOOP;
 SELECT jsonb_agg(value ORDER BY value->>'item_id') INTO v_items FROM jsonb_array_elements(v_items);
 v_fp:=md5(jsonb_build_object('actor',v_actor,'org',v_org,'os',p_os_id,'observed',p_os_observed,'origin','manual','items',v_items,'data',p_dados)::text);
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('delivery_request:'||jsonb_build_array(v_org,v_actor,'group',p_request_key)::text,0));
 IF platform_private.delivery_actor_20261030('group') IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'DELIVERY_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
 -- Canonical global gate is acquired BEFORE every OS/stock row lock.
 PERFORM platform_private.delivery_gate_20261030(v_org,'group');
 SELECT * INTO v_os FROM public.ordens_servico WHERE id=p_os_id AND organization_id=v_org FOR UPDATE;
 IF NOT FOUND OR v_os.partner_order_id IS NOT NULL OR v_os.origem IS DISTINCT FROM 'agronomica' THEN RAISE EXCEPTION 'DELIVERY_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF v_os.cliente_id IS DISTINCT FROM v_original_client OR v_os.updated_at IS DISTINCT FROM p_os_observed THEN RAISE EXCEPTION 'DELIVERY_OBSERVED_CONFLICT' USING ERRCODE='PT409'; END IF;
 PERFORM 1 FROM public.clientes WHERE id=v_os.cliente_id AND organization_id=v_org FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) LOOP
  v_id:=(v_item->>'item_id')::uuid;
  PERFORM 1 FROM public.estoque_produto WHERE id=v_id FOR UPDATE;
  PERFORM platform_private.stock_motor_item(v_id,'reserva',jsonb_build_object('os_id',p_os_id,'os_tipo','manual','cliente_id',v_os.cliente_id));
  IF platform_private.delivery_actor_20261030('group') IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'DELIVERY_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
 END LOOP;
 PERFORM platform_private.delivery_gate_20261030(v_org,'group');
 SELECT * INTO v_prev FROM platform_private.delivery_requests_20261030 WHERE request_key=p_request_key AND actor=v_actor AND organization_id=v_org AND action='group';
 IF FOUND THEN
  IF v_prev.actor IS DISTINCT FROM v_actor OR v_prev.organization_id IS DISTINCT FROM v_org OR v_prev.action IS DISTINCT FROM 'group' OR v_prev.fingerprint IS DISTINCT FROM v_fp THEN RAISE EXCEPTION 'DELIVERY_REPLAY_CONFLICT' USING ERRCODE='PT409'; END IF;
  RETURN v_prev.result||jsonb_build_object('replay',true);
 END IF;
 IF v_os.updated_at IS DISTINCT FROM p_os_observed OR v_os.status::text<>'pronto_entrega' THEN RAISE EXCEPTION 'DELIVERY_OBSERVED_CONFLICT' USING ERRCODE='PT409'; END IF;
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) LOOP
  SELECT updated_at INTO v_current FROM public.estoque_produto WHERE id=(v_item->>'item_id')::uuid;
  IF v_current IS DISTINCT FROM (v_item->>'observed_updated_at')::timestamptz THEN RAISE EXCEPTION 'DELIVERY_OBSERVED_CONFLICT' USING ERRCODE='PT409'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.entregas WHERE ordem_servico_id=p_os_id AND status::text<>'cancelada' AND estoque_produto_id IN (SELECT (value->>'item_id')::uuid FROM jsonb_array_elements(v_items))) THEN RAISE EXCEPTION 'DELIVERY_EXISTING_UNOWNED' USING ERRCODE='PT409'; END IF;
 INSERT INTO platform_private.delivery_context_20261030(txid,actor,organization_id,action,target) VALUES(pg_catalog.txid_current(),v_actor,v_org,'group',p_os_id);
 v_batch:=public.rpc_estoque_reservar_v1(p_os_id,'manual',(SELECT jsonb_agg(value-'observed_updated_at') FROM jsonb_array_elements(v_items)),'delivery-reserve:'||md5(jsonb_build_array(v_actor,v_org,p_request_key)::text),jsonb_build_object('cliente_id',v_os.cliente_id));
 IF v_batch->>'ok' IS DISTINCT FROM 'true' OR v_batch->>'replay' IS DISTINCT FROM 'false' OR jsonb_array_length(v_batch->'itens')<>jsonb_array_length(v_items) THEN RAISE EXCEPTION 'DELIVERY_RESERVE_ACK_INVALID' USING ERRCODE='PT409'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.stock_batch_requests WHERE request_key='delivery-reserve:'||md5(jsonb_build_array(v_actor,v_org,p_request_key)::text) AND result=v_batch) THEN RAISE EXCEPTION 'DELIVERY_RESERVE_ACK_INVALID' USING ERRCODE='PT409'; END IF;
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) LOOP
  v_reserved:=(v_batch->'itens'->>v_index)::uuid; v_qty:=(v_item->>'quantidade')::numeric;
  IF v_reserved IS NULL THEN RAISE EXCEPTION 'DELIVERY_RESERVE_ACK_INVALID' USING ERRCODE='PT409'; END IF;
  PERFORM platform_private.delivery_gate_20261030(v_org,'group');
  UPDATE platform_private.delivery_context_20261030 SET item=v_reserved,delivery=NULL,mutation='create' WHERE txid=pg_catalog.txid_current();
  v_call:=public.rpc_cockpit_criar_entrega_v1(p_os_id,'manual',v_reserved,v_qty,p_dados||jsonb_build_object('cliente_id',v_os.cliente_id));
  IF v_call->>'success' IS DISTINCT FROM 'true' OR v_call->>'replay' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'DELIVERY_CREATE_ACK_INVALID' USING ERRCODE='PT409'; END IF;
  v_ent:=(v_call->>'entrega_id')::uuid;
  IF v_ent IS NULL OR NOT EXISTS(SELECT 1 FROM public.entregas WHERE id=v_ent AND organization_id=v_org AND ordem_servico_id=p_os_id AND estoque_produto_id=v_reserved AND quantidade_entregue=v_qty AND receivable_id IS NULL AND partner_order_id IS NULL) THEN RAISE EXCEPTION 'DELIVERY_CREATE_ACK_INVALID' USING ERRCODE='PT409'; END IF;
  v_call:=public.rpc_estoque_operar_v1('expedicao',v_reserved,v_qty,'delivery-exp:'||md5(jsonb_build_array(v_actor,v_org,p_request_key,v_index)::text),jsonb_build_object('referencia_tipo','entrega','referencia_id',v_ent,'os_id',p_os_id,'os_tipo','manual','cliente_id',v_os.cliente_id));
  IF v_call->>'ok' IS DISTINCT FROM 'true' OR v_call->>'replay' IS DISTINCT FROM 'false' OR NOT EXISTS(SELECT 1 FROM public.estoque_movimentacoes WHERE id=(v_call->>'movimentacao_id')::uuid AND estoque_produto_id=v_reserved AND referencia_id=v_ent AND referencia_tipo='entrega' AND acao='expedicao' AND usuario_id=v_actor) THEN RAISE EXCEPTION 'DELIVERY_MOVE_ACK_INVALID' USING ERRCODE='PT409'; END IF;
  PERFORM platform_private.delivery_gate_20261030(v_org,'group');
  v_result:=v_result||jsonb_build_array(jsonb_build_object('entrega_id',v_ent,'estoque_produto_id',v_reserved,'movimentacao_id',v_call->>'movimentacao_id'));
  v_index:=v_index+1;
 END LOOP;
 v_call:=jsonb_build_object('success',true,'replay',false,'organization_id',v_org,'os_id',p_os_id,'itens',v_result);
 INSERT INTO platform_private.delivery_requests_20261030(request_key,actor,organization_id,action,fingerprint,result) VALUES(p_request_key,v_actor,v_org,'group',v_fp,v_call);
 DELETE FROM platform_private.delivery_context_20261030 WHERE txid=pg_catalog.txid_current();
 RETURN v_call;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_entrega_cancelar_v1(p_entrega_id uuid, p_motivo text, p_observed timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '3s'
AS $function$
DECLARE v_org uuid; v_actor uuid:=auth.uid(); v_e public.entregas%ROWTYPE; v_s public.estoque_produto%ROWTYPE;
 v_m public.estoque_movimentacoes%ROWTYPE; v_result jsonb; v_key text; v_fp text; v_prev platform_private.delivery_requests_20261030%ROWTYPE;
BEGIN
 v_org:=platform_private.delivery_actor_20261030('cancel');
 IF p_entrega_id IS NULL OR p_motivo IS NULL OR length(btrim(p_motivo))=0 OR p_observed IS NULL THEN RAISE EXCEPTION 'DELIVERY_CANCEL_INVALID' USING ERRCODE='22023'; END IF;
 SELECT * INTO v_e FROM public.entregas WHERE id=p_entrega_id AND organization_id=v_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('entrega_cancelar:'||p_entrega_id::text));
 IF platform_private.delivery_actor_20261030('cancel') IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'DELIVERY_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
 PERFORM platform_private.delivery_gate_20261030(v_org,'cancel');
 SELECT * INTO v_e FROM public.entregas WHERE id=p_entrega_id AND organization_id=v_org FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF platform_private.delivery_actor_20261030('cancel') IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'DELIVERY_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
 IF v_e.ordem_servico_onfarm_id IS NOT NULL OR v_e.partner_order_id IS NOT NULL OR v_e.receivable_id IS NOT NULL OR v_e.status::text='entregue'
 OR NOT EXISTS(SELECT 1 FROM public.ordens_servico WHERE id=v_e.ordem_servico_id AND organization_id=v_org AND origem='agronomica' AND partner_order_id IS NULL)
 THEN RAISE EXCEPTION 'DELIVERY_CANCEL_ORIGIN_CLOSED' USING ERRCODE='42501'; END IF;
 v_key:='cancel:'||p_entrega_id::text; v_fp:=md5(jsonb_build_array(v_actor,v_org,p_entrega_id,btrim(p_motivo),p_observed)::text);
 SELECT * INTO v_s FROM public.estoque_produto WHERE id=v_e.estoque_produto_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_STOCK_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM platform_private.stock_motor_item(v_s.id,'cancelamento_reserva',jsonb_build_object('referencia_tipo','entrega','referencia_id',v_e.id));
 PERFORM platform_private.delivery_gate_20261030(v_org,'cancel');
 PERFORM 1 FROM public.ordens_servico WHERE id=v_e.ordem_servico_id AND organization_id=v_org AND origem='agronomica' AND partner_order_id IS NULL AND cliente_id=v_e.cliente_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_CANCEL_ORIGIN_CLOSED' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.clientes WHERE id=v_e.cliente_id AND organization_id=v_org FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM platform_private.delivery_gate_20261030(v_org,'cancel');
 SELECT * INTO v_prev FROM platform_private.delivery_requests_20261030 WHERE request_key=v_key AND actor=v_actor AND organization_id=v_org AND action='cancel';
 IF FOUND THEN
  IF v_prev.actor IS DISTINCT FROM v_actor OR v_prev.organization_id IS DISTINCT FROM v_org OR v_prev.fingerprint IS DISTINCT FROM v_fp OR v_prev.action IS DISTINCT FROM 'cancel' OR v_e.status::text<>'cancelada' THEN RAISE EXCEPTION 'DELIVERY_REPLAY_CONFLICT' USING ERRCODE='PT409'; END IF;
  RETURN v_prev.result||jsonb_build_object('replay',true);
 END IF;
 IF v_e.updated_at IS DISTINCT FROM p_observed THEN RAISE EXCEPTION 'DELIVERY_OBSERVED_CONFLICT' USING ERRCODE='PT409'; END IF;
 IF v_e.status::text NOT IN ('separado','em_rota') OR v_s.reservado_para_os_id IS DISTINCT FROM v_e.ordem_servico_id OR v_s.reservado_para_os_tipo IS DISTINCT FROM 'manual' THEN RAISE EXCEPTION 'DELIVERY_CANCEL_STATE_CONFLICT' USING ERRCODE='PT409'; END IF;
 INSERT INTO platform_private.delivery_context_20261030(txid,actor,organization_id,action,target) VALUES(pg_catalog.txid_current(),v_actor,v_org,'cancel',v_e.id);
 IF (SELECT count(*) FROM public.estoque_movimentacoes WHERE estoque_produto_id=v_s.id AND referencia_tipo='entrega' AND referencia_id=v_e.id AND acao='expedicao')<>1 THEN RAISE EXCEPTION 'DELIVERY_CANCEL_LEDGER_UNPROVEN' USING ERRCODE='PT409'; END IF;
 SELECT * INTO v_m FROM public.estoque_movimentacoes WHERE estoque_produto_id=v_s.id AND referencia_tipo='entrega' AND referencia_id=v_e.id AND acao='expedicao' FOR UPDATE;
 v_result:=public.rpc_estoque_operar_v1('estorno_expedicao',v_s.id,NULL,'delivery-cancel-exp:'||v_e.id::text,jsonb_build_object('referencia_tipo','entrega','referencia_id',v_e.id,'movimentacao_origem_id',v_m.id,'motivo',btrim(p_motivo)));
 IF v_result->>'ok' IS DISTINCT FROM 'true' OR v_result->>'replay' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'DELIVERY_CANCEL_ACK_INVALID' USING ERRCODE='PT409'; END IF;
 PERFORM platform_private.delivery_gate_20261030(v_org,'cancel');
 SELECT * INTO v_s FROM public.estoque_produto WHERE id=v_e.estoque_produto_id;
 IF v_s.status::text<>'reservado' OR v_s.quantidade_reservada IS DISTINCT FROM v_e.quantidade_entregue THEN RAISE EXCEPTION 'DELIVERY_CANCEL_BALANCE_CONFLICT' USING ERRCODE='PT409'; END IF;
 v_result:=public.rpc_estoque_operar_v1('cancelamento_reserva',v_s.id,v_s.quantidade_reservada,'delivery-cancel-res:'||v_e.id::text,jsonb_build_object('referencia_tipo','entrega','referencia_id',v_e.id,'motivo',btrim(p_motivo)));
 IF v_result->>'ok' IS DISTINCT FROM 'true' OR v_result->>'replay' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'DELIVERY_CANCEL_ACK_INVALID' USING ERRCODE='PT409'; END IF;
 PERFORM platform_private.delivery_gate_20261030(v_org,'cancel');
 UPDATE platform_private.delivery_context_20261030 SET mutation='cancel' WHERE txid=pg_catalog.txid_current();
 UPDATE public.entregas SET status='cancelada',motivo_cancelamento=btrim(p_motivo) WHERE id=v_e.id AND organization_id=v_org;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM platform_private.delivery_context_20261030 WHERE txid=pg_catalog.txid_current() AND consumed) THEN RAISE EXCEPTION 'DELIVERY_CANCEL_TICKET_INVALID' USING ERRCODE='42501'; END IF;
 v_result:=jsonb_build_object('success',true,'replay',false,'organization_id',v_org,'entrega_id',v_e.id,'estoque_estornado',true,'reserva_liberada',true);
 INSERT INTO platform_private.delivery_requests_20261030(request_key,actor,organization_id,action,fingerprint,result) VALUES(v_key,v_actor,v_org,'cancel',v_fp,v_result);
 DELETE FROM platform_private.delivery_context_20261030 WHERE txid=pg_catalog.txid_current();
 RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_estoque_operar_v1(p_acao text, p_item_id uuid, p_quantidade numeric DEFAULT NULL::numeric, p_idempotency_key text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_fp text;
  v_prev public.estoque_movimentacoes%ROWTYPE;
  v_item public.estoque_produto%ROWTYPE;
  v_after public.estoque_produto%ROWTYPE;
  v_mov public.estoque_movimentacoes%ROWTYPE;
  v_ctx jsonb;
  v_qtd numeric := p_quantidade;
  v_motivo text := NULLIF(p_payload->>'motivo','');
  v_origem_mov uuid;
  v_limite numeric;
  v_classif text;
  v_target_id uuid;
  v_lote public.lotes%ROWTYPE;
BEGIN
  PERFORM platform_private.stock_motor_context_set(NULL);
  PERFORM platform_private.stock_motor_actor(p_acao);
  IF (p_quantidade IS NULL AND p_acao IS DISTINCT FROM 'estorno_expedicao') OR
     (p_quantidade IS NOT NULL AND (p_quantidade::text IN ('NaN','Infinity','-Infinity') OR p_quantidade <= 0)) THEN
    RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA: quantidade deve ser finita e maior que zero.' USING ERRCODE='23514';
  END IF;
  IF p_acao = 'ajuste' AND p_payload->>'sentido' IS NOT NULL AND p_payload->>'sentido' NOT IN ('entrada','saida') THEN
    RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO: sentido deve ser entrada ou saida.' USING ERRCODE='22023';
  END IF;
  PERFORM platform_private.stock_motor_item(p_item_id,p_acao,p_payload);
  v_origem_mov := NULLIF(p_payload->>'movimentacao_origem_id','')::uuid;
  IF p_acao IS NULL OR p_acao NOT IN
     ('reserva','cancelamento_reserva','expedicao','entrega','estorno_expedicao','ajuste','perda','descarte','devolucao') THEN
    RAISE EXCEPTION 'ESTQ_ACAO_INVALIDA: ação % não é suportada pelo motor canônico.', p_acao
      USING ERRCODE='check_violation';
  END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'ESTQ_NAO_AUTENTICADO' USING ERRCODE='insufficient_privilege';
  END IF;
  IF NOT public.fn_estoque_pode_operar(v_uid, p_acao) THEN
    RAISE EXCEPTION 'ESTQ_SEM_PERMISSAO: perfil não autorizado para %.', p_acao
      USING ERRCODE='insufficient_privilege';
  END IF;
  IF p_idempotency_key IS NULL OR length(trim(p_idempotency_key)) < 8 THEN
    RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_OBRIGATORIA: informe uma chave com ao menos 8 caracteres.'
      USING ERRCODE='check_violation';
  END IF;

  SELECT * INTO v_item FROM public.estoque_produto WHERE id=p_item_id FOR UPDATE;
  PERFORM platform_private.stock_motor_context_set(NULL);
  PERFORM platform_private.stock_motor_actor(p_acao);
  IF (p_quantidade IS NULL AND p_acao IS DISTINCT FROM 'estorno_expedicao') OR
     (p_quantidade IS NOT NULL AND (p_quantidade::text IN ('NaN','Infinity','-Infinity') OR p_quantidade <= 0)) THEN
    RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA: quantidade deve ser finita e maior que zero.' USING ERRCODE='23514';
  END IF;
  IF p_acao = 'ajuste' AND p_payload->>'sentido' IS NOT NULL AND p_payload->>'sentido' NOT IN ('entrada','saida') THEN
    RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO: sentido deve ser entrada ou saida.' USING ERRCODE='22023';
  END IF;
  PERFORM platform_private.stock_motor_item(p_item_id,p_acao,p_payload);
  v_fp := public.fn_estoque_fingerprint(p_acao, p_item_id, p_quantidade, p_payload);
  PERFORM pg_advisory_xact_lock(hashtext('estoque_mov:'||p_idempotency_key));

  SELECT * INTO v_prev FROM public.estoque_movimentacoes
   WHERE idempotency_key = p_idempotency_key LIMIT 1;
  IF FOUND THEN
    IF v_prev.usuario_id IS DISTINCT FROM v_uid OR NOT coalesce(public.stock_p1_movement_owned(v_prev.estoque_produto_id,v_prev.lote_id),false) OR v_prev.metadata->>'stock_request_item' IS DISTINCT FROM p_item_id::text OR v_prev.metadata->>'stock_request_actor' IS DISTINCT FROM v_uid::text THEN
      RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO' USING ERRCODE='23505';
    END IF;
    IF v_prev.request_fingerprint IS DISTINCT FROM v_fp THEN
      RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO: chave já usada com payload divergente.'
        USING ERRCODE='23505';
    END IF;
    RETURN jsonb_build_object(
      'ok', true, 'replay', true, 'acao', v_prev.acao,
      'movimentacao_id', v_prev.id, 'estoque_produto_id', v_prev.estoque_produto_id,
      'saldo_anterior', v_prev.saldo_anterior, 'saldo_posterior', v_prev.saldo_posterior,
      'reservado_anterior', v_prev.reservado_anterior, 'reservado_posterior', v_prev.reservado_posterior,
      'status_anterior', v_prev.status_anterior, 'status_novo', v_prev.status_novo);
  END IF;

  SELECT * INTO v_item FROM public.estoque_produto WHERE id = p_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ESTQ_ITEM_INEXISTENTE: item % não encontrado.', p_item_id USING ERRCODE='no_data_found';
  END IF;

  IF p_acao <> 'estorno_expedicao' AND (v_qtd IS NULL OR v_qtd <= 0) THEN
    RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA: quantidade deve ser maior que zero.' USING ERRCODE='check_violation';
  END IF;

  v_ctx := jsonb_strip_nulls(jsonb_build_object(
    'reserve_args', jsonb_build_object('os_id',p_payload->>'os_id','os_tipo',COALESCE(p_payload->>'os_tipo','interna'),'cliente_id',NULLIF(p_payload->>'cliente_id',''),'partner_id',NULLIF(p_payload->>'partner_id',''),'partner_order_id',NULLIF(p_payload->>'partner_order_id',''),'observacao',p_payload->>'observacao'),'acao', p_acao, 'origem', COALESCE(p_payload->>'origem','rpc_estoque_operar_v1'),
    'referencia_tipo', p_payload->>'referencia_tipo', 'referencia_id', p_payload->>'referencia_id',
    'motivo', v_motivo, 'idempotency_key', p_idempotency_key, 'request_fingerprint', v_fp,
    'usuario_id', v_uid::text, 'unidade', COALESCE(p_payload->>'unidade','un'),
    'observacao', p_payload->>'observacao',
    'metadata', COALESCE(p_payload->'metadata','{}'::jsonb) || jsonb_build_object('motor','v1','stock_request_item',p_item_id::text,'stock_request_actor',v_uid::text)
  ));

  -- ---------- validações por ação ----------
  IF p_acao = 'reserva' THEN
    IF v_item.status::text <> 'disponivel' THEN
      RAISE EXCEPTION 'ESTQ_STATUS_INVALIDO: item não está disponível (%).', v_item.status USING ERRCODE='check_violation';
    END IF;
    IF v_qtd > COALESCE(v_item.quantidade,0) THEN
      RAISE EXCEPTION 'ESTQ_SALDO_INSUFICIENTE: solicitado % > disponível %.', v_qtd, COALESCE(v_item.quantidade,0)
        USING ERRCODE='check_violation';
    END IF;
    PERFORM platform_private.stock_motor_context_set(v_ctx);
    v_target_id := public.reservar_estoque_item(
      p_item_id, v_qtd, (p_payload->>'os_id')::uuid, COALESCE(p_payload->>'os_tipo','interna'),
      NULLIF(p_payload->>'cliente_id','')::uuid, NULLIF(p_payload->>'partner_id','')::uuid,
      NULLIF(p_payload->>'partner_order_id','')::uuid, p_payload->>'observacao');

  ELSIF p_acao = 'cancelamento_reserva' THEN
    IF v_item.status::text <> 'reservado' THEN
      RAISE EXCEPTION 'ESTQ_STATUS_INVALIDO: item não está reservado.' USING ERRCODE='check_violation';
    END IF;
    IF v_qtd > COALESCE(v_item.quantidade_reservada,0) THEN
      RAISE EXCEPTION 'ESTQ_LIBERACAO_EXCEDE: % > reservado %.', v_qtd, COALESCE(v_item.quantidade_reservada,0)
        USING ERRCODE='check_violation';
    END IF;
    PERFORM platform_private.stock_motor_context_set(v_ctx);
    IF v_qtd = COALESCE(v_item.quantidade_reservada,0) THEN
      IF EXISTS(SELECT 1 FROM platform_private.delivery_context_20261030 d
        WHERE d.txid=txid_current() AND d.actor=auth.uid() AND d.action='cancel'
         AND d.target=NULLIF(p_payload->>'referencia_id','')::uuid) THEN
        PERFORM platform_private.delivery_merge_split_20261030(p_item_id,v_ctx,p_payload);
      ELSE
        UPDATE public.estoque_produto SET status='disponivel' WHERE id=p_item_id;
      END IF;
    ELSE
      UPDATE public.estoque_produto SET quantidade_reservada = quantidade_reservada - v_qtd WHERE id=p_item_id;
    END IF;
    v_target_id := p_item_id;

  ELSIF p_acao = 'expedicao' THEN
    IF v_item.status::text <> 'reservado' THEN
      RAISE EXCEPTION 'ESTQ_STATUS_INVALIDO: só é possível expedir item reservado.' USING ERRCODE='check_violation';
    END IF;
    IF v_qtd > COALESCE(v_item.quantidade_reservada,0) THEN
      RAISE EXCEPTION 'ESTQ_EXPEDICAO_EXCEDE: % > reservado %.', v_qtd, COALESCE(v_item.quantidade_reservada,0)
        USING ERRCODE='check_violation';
    END IF;
    IF (p_payload->>'cliente_id') IS NOT NULL
       AND v_item.reservado_para_cliente_id IS NOT NULL
       AND v_item.reservado_para_cliente_id <> (p_payload->>'cliente_id')::uuid THEN
      RAISE EXCEPTION 'ESTQ_ESCOPO_INVALIDO: item reservado para outro cliente.' USING ERRCODE='insufficient_privilege';
    END IF;
    IF (p_payload->>'os_id') IS NOT NULL
       AND v_item.reservado_para_os_id IS NOT NULL
       AND v_item.reservado_para_os_id <> (p_payload->>'os_id')::uuid THEN
      RAISE EXCEPTION 'ESTQ_ESCOPO_INVALIDO: item reservado para outra OS/pedido.' USING ERRCODE='insufficient_privilege';
    END IF;
    PERFORM platform_private.stock_motor_context_set(v_ctx);
    IF v_qtd = COALESCE(v_item.quantidade_reservada,0) THEN
      UPDATE public.estoque_produto SET status='expedido', expedido_em=now(), expedido_por=v_uid WHERE id=p_item_id;
    ELSE
      -- expedição parcial: baixa somente a quantidade autorizada
      UPDATE public.estoque_produto
         SET quantidade = GREATEST(COALESCE(quantidade,0) - v_qtd, 0),
             quantidade_reservada = COALESCE(quantidade_reservada,0) - v_qtd
       WHERE id = p_item_id;
    END IF;
    v_target_id := p_item_id;

  ELSIF p_acao = 'entrega' THEN
    IF v_item.status::text NOT IN ('reservado','expedido') THEN
      RAISE EXCEPTION 'ESTQ_STATUS_INVALIDO: entrega exige item reservado ou expedido.' USING ERRCODE='check_violation';
    END IF;
    IF v_qtd > COALESCE(v_item.quantidade,0) THEN
      RAISE EXCEPTION 'ESTQ_SALDO_INSUFICIENTE: entrega % > saldo %.', v_qtd, COALESCE(v_item.quantidade,0)
        USING ERRCODE='check_violation';
    END IF;
    PERFORM platform_private.stock_motor_context_set(v_ctx);
    UPDATE public.estoque_produto
       SET quantidade = COALESCE(quantidade,0) - v_qtd,
           quantidade_reservada = GREATEST(COALESCE(quantidade_reservada,0) - v_qtd, 0),
           status = 'expedido', expedido_em = COALESCE(expedido_em, now()), expedido_por = COALESCE(expedido_por, v_uid)
     WHERE id = p_item_id;
    v_target_id := p_item_id;

  ELSIF p_acao = 'estorno_expedicao' THEN
    IF v_origem_mov IS NULL THEN
      RAISE EXCEPTION 'ESTQ_ESTORNO_SEM_ORIGEM: informe movimentacao_origem_id.' USING ERRCODE='check_violation';
    END IF;
    SELECT * INTO v_mov FROM public.estoque_movimentacoes WHERE id = v_origem_mov;
    IF NOT FOUND OR v_mov.estoque_produto_id <> p_item_id THEN
      RAISE EXCEPTION 'ESTQ_ESTORNO_ORIGEM_INVALIDA' USING ERRCODE='check_violation';
    END IF;
    IF v_mov.acao IN ('estorno_expedicao','devolucao') THEN
      RAISE EXCEPTION 'ESTQ_ESTORNO_DE_ESTORNO: operação não permitida.' USING ERRCODE='check_violation';
    END IF;
    IF v_mov.acao NOT IN ('expedicao','entrega') THEN
      RAISE EXCEPTION 'ESTQ_ESTORNO_ACAO_INVALIDA: só expedição/entrega pode ser estornada.' USING ERRCODE='check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM public.estoque_movimentacoes WHERE movimentacao_origem_id = v_origem_mov) THEN
      RAISE EXCEPTION 'ESTQ_ESTORNO_DUPLICADO: movimentação já estornada.' USING ERRCODE='23505';
    END IF;
    v_qtd := COALESCE(v_qtd, v_mov.quantidade);
    v_ctx := v_ctx || jsonb_build_object('movimentacao_origem_id', v_origem_mov::text);
    PERFORM platform_private.stock_motor_context_set(v_ctx);
    UPDATE public.estoque_produto
       SET quantidade = COALESCE(quantidade,0) + COALESCE(v_mov.saldo_anterior,0) - COALESCE(v_mov.saldo_posterior,0),
           quantidade_reservada = COALESCE(v_mov.reservado_anterior, quantidade_reservada),
           status = COALESCE(v_mov.status_anterior, status::text)::status_estoque,
           expedido_em = NULL, expedido_por = NULL
     WHERE id = p_item_id;
    v_target_id := p_item_id;

  ELSIF p_acao IN ('ajuste','perda','descarte') THEN
    IF v_motivo IS NULL THEN
      RAISE EXCEPTION 'ESTQ_MOTIVO_OBRIGATORIO: informe o motivo para %.', p_acao USING ERRCODE='check_violation';
    END IF;
    SELECT limite_ajuste_sem_aprovacao INTO v_limite FROM public.estoque_politicas LIMIT 1;
    IF p_acao <> 'ajuste' OR COALESCE(p_payload->>'sentido','saida') = 'saida' THEN
      IF v_qtd > COALESCE(v_limite,10)
         AND NOT (public.has_role(v_uid,'administrador'::app_role) OR public.has_role(v_uid,'gestor'::app_role)) THEN
        RAISE EXCEPTION 'ESTQ_APROVACAO_REQUERIDA: redução de % excede o limite % sem aprovação.', v_qtd, v_limite
          USING ERRCODE='insufficient_privilege';
      END IF;
      IF v_qtd > COALESCE(v_item.quantidade,0) THEN
        RAISE EXCEPTION 'ESTQ_SALDO_INSUFICIENTE: redução % > saldo %.', v_qtd, COALESCE(v_item.quantidade,0)
          USING ERRCODE='check_violation';
      END IF;
      PERFORM platform_private.stock_motor_context_set(v_ctx);
      UPDATE public.estoque_produto
         SET quantidade = COALESCE(quantidade,0) - v_qtd,
             quantidade_reservada = LEAST(COALESCE(quantidade_reservada,0), COALESCE(quantidade,0) - v_qtd)
       WHERE id = p_item_id;
    ELSE
      PERFORM platform_private.stock_motor_context_set(v_ctx);
      UPDATE public.estoque_produto SET quantidade = COALESCE(quantidade,0) + v_qtd WHERE id = p_item_id;
    END IF;
    v_target_id := p_item_id;

  ELSIF p_acao = 'devolucao' THEN
    v_classif := NULLIF(p_payload->>'classificacao','');
    IF v_classif IS NULL OR v_classif NOT IN ('reintegravel','quarentena','descarte','reprocesso') THEN
      RAISE EXCEPTION 'ESTQ_DEVOLUCAO_CLASSIFICACAO: informe reintegravel|quarentena|descarte|reprocesso.'
        USING ERRCODE='check_violation';
    END IF;
    IF v_motivo IS NULL THEN
      RAISE EXCEPTION 'ESTQ_MOTIVO_OBRIGATORIO: informe o motivo da devolução.' USING ERRCODE='check_violation';
    END IF;
    IF v_classif = 'reintegravel' THEN
      SELECT * INTO v_lote FROM public.lotes WHERE id = v_item.lote_id;
      IF NOT EXISTS (SELECT 1 FROM public.controle_qualidade cq
                      WHERE cq.lote_id = v_item.lote_id AND cq.resultado = 'aprovado'::resultado_cq) THEN
        RAISE EXCEPTION 'ESTQ_DEVOLUCAO_CQ: lote sem CQ aprovado não pode ser reintegrado ao estoque comercial.'
          USING ERRCODE='check_violation';
      END IF;
      IF v_item.validade IS NOT NULL AND v_item.validade < current_date THEN
        RAISE EXCEPTION 'ESTQ_DEVOLUCAO_VALIDADE: item vencido não pode ser reintegrado.' USING ERRCODE='check_violation';
      END IF;
      v_ctx := v_ctx || jsonb_build_object('metadata',
        COALESCE(v_ctx->'metadata','{}'::jsonb) || jsonb_build_object('classificacao', v_classif));
      PERFORM platform_private.stock_motor_context_set(v_ctx);
      UPDATE public.estoque_produto SET quantidade = COALESCE(quantidade,0) + v_qtd WHERE id = p_item_id;
    ELSE
      v_ctx := v_ctx || jsonb_build_object('metadata',
        COALESCE(v_ctx->'metadata','{}'::jsonb) || jsonb_build_object('classificacao', v_classif, 'reintegrado', false));
      PERFORM platform_private.stock_motor_context_set(v_ctx);
      -- não reintegra saldo comercial: registra apenas a trilha da devolução
      UPDATE public.estoque_produto SET observacao_reserva = COALESCE(observacao_reserva, v_motivo) WHERE id = p_item_id;
      INSERT INTO public.estoque_movimentacoes
        (estoque_produto_id, acao, quantidade, status_anterior, status_novo, lote_id, usuario_id,
         saldo_anterior, saldo_posterior, reservado_anterior, reservado_posterior,
         unidade, direcao, origem, referencia_tipo, referencia_id, motivo,
         idempotency_key, request_fingerprint, metadata)
      VALUES (p_item_id, 'devolucao', v_qtd, v_item.status::text, v_item.status::text, v_item.lote_id, v_uid,
         COALESCE(v_item.quantidade,0), COALESCE(v_item.quantidade,0),
         COALESCE(v_item.quantidade_reservada,0), COALESCE(v_item.quantidade_reservada,0),
         COALESCE(p_payload->>'unidade','un'), 'neutro',
         COALESCE(p_payload->>'origem','rpc_estoque_operar_v1'),
         p_payload->>'referencia_tipo', NULLIF(p_payload->>'referencia_id','')::uuid, v_motivo,
         p_idempotency_key, v_fp,
         jsonb_build_object('classificacao', v_classif, 'reintegrado', false, 'motor','v1','stock_request_item',p_item_id::text,'stock_request_actor',v_uid::text));
    END IF;
    v_target_id := p_item_id;
  END IF;

  PERFORM platform_private.stock_motor_context_set(NULL); PERFORM public.fn_estoque_ctx_close();

  SELECT * INTO v_after FROM public.estoque_produto WHERE id = COALESCE(v_target_id, p_item_id);
  SELECT * INTO v_mov FROM public.estoque_movimentacoes
   WHERE idempotency_key = p_idempotency_key ORDER BY created_at DESC LIMIT 1;

  IF v_mov.id IS NULL THEN
    RAISE EXCEPTION 'ESTQ_SEM_TRILHA: operação não gerou lançamento no livro.' USING ERRCODE='internal_error';
  END IF;
  IF COALESCE(v_after.quantidade,0) < 0 OR COALESCE(v_after.quantidade_reservada,0) < 0 THEN
    RAISE EXCEPTION 'ESTQ_SALDO_NEGATIVO: operação resultaria em saldo negativo.' USING ERRCODE='check_violation';
  END IF;
  IF COALESCE(v_after.quantidade_reservada,0) > COALESCE(v_after.quantidade,0) THEN
    RAISE EXCEPTION 'ESTQ_RESERVA_MAIOR_QUE_SALDO' USING ERRCODE='check_violation';
  END IF;

  IF v_mov.usuario_id IS DISTINCT FROM v_uid OR v_mov.metadata->>'stock_request_item' IS DISTINCT FROM p_item_id::text OR NOT coalesce(public.stock_p1_movement_owned(v_mov.estoque_produto_id,v_mov.lote_id),false) THEN RAISE EXCEPTION 'ESTQ_SEM_TRILHA' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object(
    'ok', true, 'replay', false, 'acao', p_acao,
    'movimentacao_id', v_mov.id, 'estoque_produto_id', COALESCE(v_target_id, p_item_id),
    'saldo_anterior', v_mov.saldo_anterior, 'saldo_posterior', v_mov.saldo_posterior,
    'reservado_anterior', v_mov.reservado_anterior, 'reservado_posterior', v_mov.reservado_posterior,
    'status_anterior', v_mov.status_anterior, 'status_novo', v_mov.status_novo,
    'quantidade', v_mov.quantidade, 'unidade', v_mov.unidade);
EXCEPTION WHEN OTHERS THEN PERFORM platform_private.stock_motor_context_set(NULL); PERFORM public.fn_estoque_ctx_close(); RAISE;
END; $function$

CREATE OR REPLACE FUNCTION public.rpc_estoque_reservar_v1(p_os_id uuid, p_origem text, p_itens jsonb, p_idempotency_key text, p_dados jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_org uuid; v_actor uuid:=auth.uid(); v_tipo text; v_cliente uuid; v_partner uuid; v_order uuid; v_obs text;
 v_item jsonb; v_qty numeric; v_id uuid; v_payload jsonb; v_items jsonb; v_fp text; v_key text;
 v_prev platform_private.stock_batch_requests%ROWTYPE; v_result jsonb; v_call jsonb; v_ids uuid[]:=ARRAY[]::uuid[];
BEGIN
 v_org:=platform_private.stock_motor_actor('reserva');
 PERFORM platform_private.stock_motor_context_set(NULL);
 IF p_os_id IS NULL THEN RAISE EXCEPTION 'ESTQ_OS_OBRIGATORIA' USING ERRCODE='23514'; END IF;
 IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key))<8 OR length(p_idempotency_key)>200 THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_OBRIGATORIA' USING ERRCODE='23514'; END IF;
 IF p_origem IS NULL OR p_origem NOT IN ('padrao','manual','onfarm','on_farm','b2b') THEN RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
 v_tipo:=CASE WHEN p_origem='padrao' THEN 'manual' WHEN p_origem='on_farm' THEN 'onfarm' ELSE p_origem END;
 IF p_dados IS NULL OR jsonb_typeof(p_dados)<>'object' THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(p_dados) e WHERE e.key NOT IN ('cliente_id','partner_id','partner_order_id','observacao') OR jsonb_typeof(e.value) NOT IN ('string','null')) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 IF p_itens IS NULL OR jsonb_typeof(p_itens)<>'array' THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 IF jsonb_array_length(p_itens)=0 THEN RAISE EXCEPTION 'ESTQ_ITENS_VAZIOS' USING ERRCODE='23514'; END IF;
 v_cliente:=nullif(p_dados->>'cliente_id','')::uuid; v_partner:=nullif(p_dados->>'partner_id','')::uuid; v_order:=nullif(p_dados->>'partner_order_id','')::uuid; v_obs:=nullif(p_dados->>'observacao','');
 v_payload:=jsonb_build_object('os_id',p_os_id,'os_tipo',v_tipo,'cliente_id',v_cliente,'partner_id',v_partner,'partner_order_id',v_order,'observacao',v_obs);
 v_items:='[]'::jsonb;
 FOR v_item IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
  IF jsonb_typeof(v_item)<>'object' OR NOT(v_item ? 'item_id' AND v_item ? 'quantidade') THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_each(v_item) e WHERE e.key NOT IN ('item_id','quantidade') OR (e.key='item_id' AND jsonb_typeof(e.value)<>'string') OR (e.key='quantidade' AND jsonb_typeof(e.value) NOT IN ('string','number'))) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  v_id:=(v_item->>'item_id')::uuid; v_qty:=(v_item->>'quantidade')::numeric;
  IF v_qty IS NULL OR v_qty::text IN ('NaN','Infinity','-Infinity') OR v_qty<=0 THEN RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA' USING ERRCODE='23514'; END IF;
  PERFORM platform_private.stock_motor_item(v_id,'reserva',v_payload);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_items) e WHERE e->>'item_id'=v_id::text) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  v_items:=v_items||jsonb_build_array(jsonb_build_object('item_id',v_id,'quantidade',v_qty));
 END LOOP;
 SELECT jsonb_agg(value ORDER BY value->>'item_id') INTO v_items FROM jsonb_array_elements(v_items);
 v_fp:=md5(jsonb_build_object('actor',v_actor,'org',v_org,'os',p_os_id,'tipo',v_tipo,'payload',v_payload,'itens',v_items)::text);
 -- Global key collision is denied, never reused across actor/tenant/content. No wildcard comparisons.
 PERFORM pg_advisory_xact_lock(hashtextextended('stock_batch:'||p_idempotency_key,0));
 SELECT * INTO v_prev FROM platform_private.stock_batch_requests WHERE request_key=p_idempotency_key;
 IF FOUND THEN
  IF v_prev.actor IS DISTINCT FROM v_actor OR v_prev.organization_id IS DISTINCT FROM v_org OR v_prev.fingerprint IS DISTINCT FROM v_fp THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO' USING ERRCODE='23505'; END IF;
  RETURN v_prev.result||jsonb_build_object('replay',true);
 END IF;
 IF EXISTS(SELECT 1 FROM public.estoque_movimentacoes WHERE idempotency_key=p_idempotency_key OR left(idempotency_key,length(p_idempotency_key)+1)=p_idempotency_key||'#') THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO' USING ERRCODE='23505'; END IF;
 -- Consistent item order before nested motor calls; all writes are one transaction.
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) LOOP
  v_id:=(v_item->>'item_id')::uuid;
  PERFORM 1 FROM public.estoque_produto WHERE id=v_id FOR UPDATE;
  PERFORM platform_private.stock_motor_item(v_id,'reserva',v_payload);
 END LOOP;
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) LOOP
  v_id:=(v_item->>'item_id')::uuid; v_qty:=(v_item->>'quantidade')::numeric;
  v_key:='stock_batch_item:'||md5(jsonb_build_array(p_idempotency_key,v_actor,v_org,v_id)::text);
  IF EXISTS(SELECT 1 FROM public.estoque_movimentacoes WHERE idempotency_key=v_key OR left(idempotency_key,length(v_key)+1)=v_key||'#') THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO' USING ERRCODE='23505'; END IF;
  v_call:=public.rpc_estoque_operar_v1('reserva',v_id,v_qty,v_key,v_payload);
  IF v_call->>'ok' IS DISTINCT FROM 'true' OR v_call->>'replay' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'ESTQ_SEM_TRILHA'; END IF;
  -- The ledger is canonical for the split target, not the source item.
  SELECT estoque_produto_id INTO v_id FROM public.estoque_movimentacoes WHERE id=(v_call->>'movimentacao_id')::uuid;
  IF v_id IS NULL THEN RAISE EXCEPTION 'ESTQ_SEM_TRILHA'; END IF;
  v_ids:=array_append(v_ids,v_id);
 END LOOP;
 v_result:=jsonb_build_object('ok',true,'replay',false,'itens',to_jsonb(v_ids));
 INSERT INTO platform_private.stock_batch_requests(request_key,actor,organization_id,fingerprint,result) VALUES(p_idempotency_key,v_actor,v_org,v_fp,v_result);
 PERFORM platform_private.stock_motor_context_set(NULL);
 RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.tg_auto_b2b_receivable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_settings record;
  v_should boolean := false;
BEGIN
  SELECT * INTO v_settings FROM public.partner_financial_settings WHERE partner_id = NEW.partner_id AND active = true;
  IF NOT FOUND OR NOT v_settings.auto_generate_receivable THEN RETURN NEW; END IF;
  IF NEW.receivable_generated THEN RETURN NEW; END IF;

  IF v_settings.billing_trigger = 'na_aprovacao' AND NEW.status = 'aprovado' AND OLD.status IS DISTINCT FROM 'aprovado' THEN
    v_should := true;
  ELSIF v_settings.billing_trigger = 'na_entrega' AND NEW.status = 'entregue' AND OLD.status IS DISTINCT FROM 'entregue' THEN
    v_should := true;
  ELSIF v_settings.billing_trigger = 'na_producao_finalizada' AND NEW.status = 'produzido' AND OLD.status IS DISTINCT FROM 'produzido' THEN
    v_should := true;
  END IF;

  IF v_should THEN
    BEGIN
      PERFORM public.generate_b2b_receivable_secure(NEW.id);
    EXCEPTION WHEN OTHERS THEN
      -- c2_ord_atomic_approval: sem título, a aprovação não acontece (rollback do UPDATE).
      IF v_settings.billing_trigger = 'na_aprovacao' THEN
        RAISE EXCEPTION 'B2B_APPROVAL_BILLING_FAILED: %', SQLERRM USING ERRCODE='P0001';
      END IF;
      INSERT INTO public.partner_order_audit_logs(order_id, partner_id, acao, dados_novos)
      VALUES (NEW.id, NEW.partner_id, 'financeiro_auto_falhou', jsonb_build_object('erro', SQLERRM));
    END;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tg_b2b_block_receivable_before_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_status partner_order_status;
BEGIN
  IF NEW.partner_order_id IS NULL THEN RETURN NEW; END IF;
  SELECT status INTO v_status FROM public.partner_orders WHERE id = NEW.partner_order_id;
  IF v_status IS NULL THEN
    RAISE EXCEPTION 'order_not_found';
  END IF;
  IF NOT public.fn_b2b_status_is_approved_or_later(v_status) THEN
    RAISE EXCEPTION 'receivable_requires_approved_order: status=%', v_status
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.tg_b2b_enforce_plan_selectable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.payment_plan_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.payment_plan_id IS NOT DISTINCT FROM OLD.payment_plan_id THEN
    RETURN NEW;
  END IF;
  IF NOT public.fn_b2b_plan_selectable(NEW.payment_plan_id) THEN
    RAISE EXCEPTION 'plan_not_selectable';
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.tg_block_partner_order_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF public.partner_order_has_production(OLD.id) THEN
    INSERT INTO public.partner_order_audit_logs (order_id, partner_id, usuario_id, acao, dados_anteriores)
    VALUES (OLD.id, OLD.partner_id, auth.uid(), 'exclusao_bloqueada', to_jsonb(OLD));
    RAISE EXCEPTION 'Pedido com Ordem de Produção vinculada não pode ser excluído.';
  END IF;
  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_block_planning_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM public.production_order_link WHERE planning_id = OLD.id) THEN
    RAISE EXCEPTION 'Planejamento com OP gerada não pode ser excluído.';
  END IF;
  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_notify_payment_terms_pending()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_should_notify boolean := false;
  v_msg text;
BEGIN
  IF NEW.requires_financial_approval IS DISTINCT FROM true
     OR NEW.financial_approval_status IS DISTINCT FROM 'pending' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_should_notify := true;
  ELSE
    -- Só notifica quando entra em pending vindo de outro estado
    IF COALESCE(OLD.requires_financial_approval, false) = false
       OR COALESCE(OLD.financial_approval_status, 'not_required') <> 'pending' THEN
      v_should_notify := true;
    END IF;
  END IF;

  IF NOT v_should_notify THEN
    RETURN NEW;
  END IF;

  v_msg := format('Pedido B2B %s aguarda aprovação da condição de pagamento.', COALESCE(NEW.numero,''));

  PERFORM public._notify_role(
    'financeiro'::app_role,
    'b2b_payment_terms_pending',
    'Aprovação financeira pendente',
    v_msg,
    '/comercial/pedidos-b2b'
  );
  PERFORM public._notify_role(
    'administrador'::app_role,
    'b2b_payment_terms_pending',
    'Aprovação financeira pendente',
    v_msg,
    '/comercial/pedidos-b2b'
  );
  PERFORM public._notify_role(
    'gestor_comercial'::app_role,
    'b2b_payment_terms_pending',
    'Aprovação financeira pendente',
    v_msg,
    '/comercial/pedidos-b2b'
  );

  -- Notifica também o criador do pedido, se identificado
  IF NEW.created_by IS NOT NULL THEN
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link, lido)
    VALUES (
      NEW.created_by,
      'b2b_payment_terms_pending',
      'Aprovação financeira pendente',
      v_msg,
      '/comercial/pedidos-b2b',
      false
    );
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_partner_orders_credit_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v jsonb;
  v_amount numeric(14,2);
  v_should_check boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status NOT IN ('rascunho') THEN v_should_check := true; END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.credit_approved_by IS NOT NULL
       AND NEW.status = 'em_analise_comercial'
       AND OLD.status = 'aguardando_aprovacao_credito'
       AND NEW.total IS NOT DISTINCT FROM OLD.total THEN
      NEW.credit_block_reason := NULL;
      RETURN NEW;
    END IF;

    IF NEW.credit_approved_by IS NOT NULL AND OLD.credit_approved_by IS NULL THEN
      NEW.credit_block_reason := NULL;
      RETURN NEW;
    END IF;

    IF OLD.credit_approved_by IS NOT NULL
       AND NEW.status = 'aprovado'
       AND OLD.status = 'em_analise_comercial'
       AND NEW.total IS NOT DISTINCT FROM OLD.total THEN
      RETURN NEW;
    END IF;

    IF NEW.status IS DISTINCT FROM OLD.status
       AND NEW.status IN ('em_analise_comercial','aprovado') THEN
      v_should_check := true;
    ELSIF (NEW.total IS DISTINCT FROM OLD.total
        OR NEW.final_amount_with_interest IS DISTINCT FROM OLD.final_amount_with_interest)
       AND NEW.status IN ('em_analise_comercial','aprovado','aguardando_aprovacao_credito') THEN
      v_should_check := true;
    END IF;
  END IF;

  IF NOT v_should_check THEN RETURN NEW; END IF;

  -- Serializa a avaliacao de credito por parceiro dentro da transacao corrente.
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_credit:' || NEW.partner_id::text, 0));

  v_amount := ROUND(COALESCE(NEW.final_amount_with_interest, NEW.total, 0), 2);
  v := public.fn_b2b_credit_exposure(NEW.partner_id, v_amount, NEW.id);

  IF (v->>'block_if_overdue')::boolean AND (v->>'tem_vencidos')::boolean THEN
    NEW.status := 'aguardando_aprovacao_credito';
    NEW.credit_block_reason := 'inadimplencia';
    RETURN NEW;
  END IF;

  IF COALESCE((v->>'credit_limit')::numeric,0) > 0
     AND (v->>'exposicao_projetada')::numeric > (v->>'credit_limit')::numeric THEN
    NEW.status := 'aguardando_aprovacao_credito';
    NEW.credit_block_reason := CASE
      WHEN (v->>'credit_limit_action') = 'approval_required' THEN 'limite_excedido'
      ELSE 'limite_excedido_bloqueado'
    END;
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tg_partner_orders_require_items()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count int;
BEGIN
  IF NEW.status = 'aprovado' AND (OLD.status IS DISTINCT FROM 'aprovado') THEN
    SELECT count(*) INTO v_count
      FROM public.partner_order_items
     WHERE order_id = NEW.id;
    IF v_count = 0 THEN
      RAISE EXCEPTION 'no_items: pedido sem itens — não pode ser aprovado';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_recalc_planning_from_entrega()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_po uuid;
BEGIN
  IF NEW.ordem_servico_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT l.partner_order_id INTO v_po
    FROM public.production_order_link l
   WHERE l.ordem_servico_id = NEW.ordem_servico_id
   LIMIT 1;

  IF v_po IS NOT NULL THEN
    PERFORM public.recalc_partner_order_production(v_po);
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_recalc_risk_on_ar_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_partner uuid;
BEGIN
  SELECT ar.partner_id INTO v_partner
  FROM public.accounts_receivable ar
  WHERE ar.id = COALESCE(NEW.receivable_id, OLD.receivable_id)
    AND ar.origin_type = 'B2B_ORDER';
  IF v_partner IS NOT NULL THEN
    PERFORM public.recalc_partner_risk_score(v_partner);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_sync_b2b_financial_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_link record;
  v_new text;
BEGIN
  SELECT * INTO v_link FROM public.partner_order_financial_links WHERE receivable_id = NEW.id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  v_new := CASE NEW.status
    WHEN 'PAID' THEN 'recebido'
    WHEN 'PARTIAL' THEN 'parcial'
    WHEN 'OVERDUE' THEN 'vencido'
    WHEN 'CANCELED' THEN 'cancelado'
    ELSE 'gerado'
  END;

  UPDATE public.partner_orders SET financial_status = v_new WHERE id = v_link.partner_order_id;
  UPDATE public.partner_order_financial_links SET financial_status = v_new WHERE id = v_link.id;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, acao, dados_novos)
  VALUES (v_link.partner_order_id, v_link.partner_id, 'financeiro_status_alterado',
    jsonb_build_object('ar_status', NEW.status, 'novo', v_new));

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.trg_entrega_sync_partner_order_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_order_id uuid;
  v_total int; v_delivered int;
BEGIN
  SELECT os.partner_order_id INTO v_partner_order_id
    FROM public.ordens_servico os WHERE os.id = COALESCE(NEW.ordem_servico_id, OLD.ordem_servico_id);
  IF v_partner_order_id IS NULL THEN RETURN NEW; END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE e.status = 'entregue')
    INTO v_total, v_delivered
    FROM public.entregas e
    JOIN public.ordens_servico os ON os.id = e.ordem_servico_id
   WHERE os.partner_order_id = v_partner_order_id;

  IF v_total > 0 AND v_delivered = v_total THEN
    UPDATE public.partner_orders SET status = 'entregue', updated_at = now()
      WHERE id = v_partner_order_id AND status <> 'entregue';
    UPDATE public.production_planning SET status = 'entregue', updated_at = now()
      WHERE partner_order_id = v_partner_order_id;
    INSERT INTO public.production_timeline_events (partner_order_id, event_type, meta)
    VALUES (v_partner_order_id, 'entrega_realizada', jsonb_build_object('total', v_total));
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.trg_partner_order_timeline()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.production_timeline_events(partner_order_id, event_type, event_at, actor_id, meta)
    VALUES (NEW.id, 'pedido_criado', NEW.created_at, NEW.created_by, '{}'::jsonb);
  ELSIF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'aprovado' THEN
      INSERT INTO public.production_timeline_events(partner_order_id, event_type, event_at, meta)
      VALUES (NEW.id, 'pedido_aprovado', now(), '{}'::jsonb);
    ELSIF NEW.status = 'em_producao' THEN
      INSERT INTO public.production_timeline_events(partner_order_id, event_type, event_at, meta)
      VALUES (NEW.id, 'producao_iniciada', now(), '{}'::jsonb);
    ELSIF NEW.status IN ('produzido','aguardando_entrega') THEN
      INSERT INTO public.production_timeline_events(partner_order_id, event_type, event_at, meta)
      VALUES (NEW.id, 'producao_finalizada', now(), '{}'::jsonb);
    ELSIF NEW.status = 'entregue' THEN
      INSERT INTO public.production_timeline_events(partner_order_id, event_type, event_at, meta)
      VALUES (NEW.id, 'entrega_realizada', now(), '{}'::jsonb);
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_estoque_entrada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Reservas parciais (têm quantidade_reservada preenchida) seguem normalmente
  IF NEW.quantidade_reservada IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Exigir envase para o lote
  IF NOT EXISTS (SELECT 1 FROM public.envase WHERE lote_id = NEW.lote_id) THEN
    RAISE EXCEPTION 'Não é possível criar entrada no estoque: o lote ainda não possui registro de envase.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Bloquear duplicidade por envase_id (não mais por lote)
  IF NEW.envase_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.estoque_produto
    WHERE envase_id = NEW.envase_id
      AND quantidade_reservada IS NULL
      AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
  ) THEN
    RAISE EXCEPTION 'Já existe entrada de estoque para este envase.'
      USING ERRCODE = 'unique_violation';
  END IF;

  -- Compat: se a entrada vier sem envase_id, manter a regra antiga de 1 por lote
  IF NEW.envase_id IS NULL AND EXISTS (
    SELECT 1 FROM public.estoque_produto
    WHERE lote_id = NEW.lote_id
      AND envase_id IS NULL
      AND quantidade_reservada IS NULL
      AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
  ) THEN
    RAISE EXCEPTION 'Já existe uma entrada de estoque agregada para este lote.'
      USING ERRCODE = 'unique_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_estoque_reserva()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status::text = 'reservado' AND (OLD.status IS DISTINCT FROM NEW.status OR OLD.status::text <> 'reservado') THEN
    IF NEW.reservado_para_os_id IS NULL THEN
      RAISE EXCEPTION 'Reserva requer uma OS vinculada.' USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.reservado_para_os_tipo = 'b2b' THEN
      IF NEW.reservado_para_partner_id IS NULL THEN
        RAISE EXCEPTION 'Reserva B2B requer um parceiro vinculado.' USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      IF NEW.reservado_para_cliente_id IS NULL AND NEW.reservado_para_partner_id IS NULL THEN
        RAISE EXCEPTION 'Reserva requer um cliente ou parceiro vinculado.' USING ERRCODE = 'check_violation';
      END IF;
    END IF;

    IF NEW.quantidade_reservada IS NULL OR NEW.quantidade_reservada <= 0 THEN
      RAISE EXCEPTION 'Informe uma quantidade reservada maior que zero.' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.quantidade IS NOT NULL AND NEW.quantidade_reservada > NEW.quantidade THEN
      RAISE EXCEPTION 'Quantidade reservada (%) excede o estoque disponível (%).', NEW.quantidade_reservada, NEW.quantidade
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.reservado_em IS NULL THEN NEW.reservado_em := now(); END IF;
    IF NEW.reservado_por IS NULL THEN NEW.reservado_por := auth.uid(); END IF;
  END IF;

  IF NEW.status::text = 'disponivel' AND OLD.status::text = 'reservado' THEN
    NEW.reservado_para_os_id := NULL;
    NEW.reservado_para_os_tipo := NULL;
    NEW.reservado_para_cliente_id := NULL;
    NEW.reservado_para_partner_id := NULL;
    NEW.reservado_para_partner_order_id := NULL;
    NEW.quantidade_reservada := NULL;
    NEW.reservado_por := NULL;
    NEW.reservado_em := NULL;
    NEW.observacao_reserva := NULL;
  END IF;

  IF NEW.status::text = 'expedido' AND OLD.status::text <> 'expedido' THEN
    IF NEW.expedido_em IS NULL THEN NEW.expedido_em := now(); END IF;
    IF NEW.expedido_por IS NULL THEN NEW.expedido_por := auth.uid(); END IF;
  END IF;

  RETURN NEW;
END;
$function$
